-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(1,1,'Coloca la barra sobre el trapecio (posición high-bar o low-bar) y desmonta del rack.'),
(1,2,'Camina hacia atrás y adopta un stance con pies al ancho de hombros y puntas ligeramente abiertas.'),
(1,3,'Inhala, presuriza el core y bloquea la espalda en posición neutra.'),
(1,4,'Inicia el descenso flexionando cadera y rodillas simultáneamente.'),
(1,5,'Desciende hasta que la cadera quede por debajo del pliegue de la rodilla.'),
(1,6,'Empuja el suelo con los pies extendiendo cadera y rodillas.'),
(1,7,'Exhala al superar el sticking point y bloquea arriba.'),

(2,1,'Coloca la barra sobre los deltoides anteriores en posición de rack frontal.'),
(2,2,'Mantén los codos altos y paralelos al suelo.'),
(2,3,'Desmonta y adopta stance ligeramente más estrecho que la sentadilla trasera.'),
(2,4,'Presuriza el core y desciende manteniendo torso vertical.'),
(2,5,'Baja hasta profundidad completa (cadera bajo la rodilla).'),
(2,6,'Empuja el suelo manteniendo los codos altos durante la subida.'),
(2,7,'Bloquea cadera y rodilla al finalizar la repetición.'),

(3,1,'Coloca el empeine de la pierna trasera sobre un banco a la altura de la rodilla.'),
(3,2,'Adelanta la pierna delantera lo suficiente para que la rodilla no sobrepase excesivamente la punta del pie.'),
(3,3,'Sostén mancuernas a los lados o una carga frontal.'),
(3,4,'Desciende flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.'),
(3,5,'Empuja el suelo con el talón delantero para volver a la posición inicial.'),
(3,6,'Completa todas las repeticiones antes de cambiar de pierna.'),

(4,1,'Sujeta una mancuerna o kettlebell frente al pecho con ambas manos.'),
(4,2,'Adopta stance al ancho de hombros con puntas ligeramente hacia fuera.'),
(4,3,'Presuriza el core y mantén el pecho arriba.'),
(4,4,'Desciende hasta profundidad completa manteniendo los codos entre las rodillas.'),
(4,5,'Empuja el suelo para volver a la posición de pie extendiendo cadera y rodillas.'),

(5,1,'Toma la barra con agarre ancho y llévala en posición overhead con brazos bloqueados.'),
(5,2,'Activa hombros y dorsales manteniendo la barra alineada sobre la coronilla.'),
(5,3,'Adopta stance al ancho de hombros con puntas hacia fuera.'),
(5,4,'Desciende manteniendo torso vertical y la barra sobre el punto medio del pie.'),
(5,5,'Alcanza profundidad completa sin perder la posición overhead.'),
(5,6,'Empuja el suelo extendiendo cadera y rodillas manteniendo brazos bloqueados.'),

(6,1,'Coloca la barra en el pliegue de los codos con las manos cruzadas o entrelazadas.'),
(6,2,'Adopta stance al ancho de hombros y mantén torso vertical.'),
(6,3,'Presuriza el core y desciende con control.'),
(6,4,'Alcanza profundidad completa manteniendo los codos altos.'),
(6,5,'Empuja el suelo para volver a la posición inicial.'),

(7,1,'Adopta stance amplio con puntas rotadas 30-45° hacia fuera.'),
(7,2,'Coloca la barra sobre el trapecio o sujeta una mancuerna frontal.'),
(7,3,'Presuriza el core y desciende empujando las rodillas en línea con las puntas.'),
(7,4,'Alcanza profundidad completa manteniendo torso vertical.'),
(7,5,'Empuja el suelo activando aductores y glúteos.'),

(8,1,'Coloca un cajón detrás de ti a la altura deseada.'),
(8,2,'Desmonta la barra del rack y adopta stance amplio.'),
(8,3,'Inicia el descenso llevando la cadera hacia atrás sobre el cajón.'),
(8,4,'Siéntate brevemente sin relajar la tensión del core.'),
(8,5,'Empuja el suelo con las piernas para volver a la posición de pie.'),

(9,1,'Desmonta la barra y adopta la posición de sentadilla trasera.'),
(9,2,'Desciende con control hasta profundidad completa.'),
(9,3,'Mantén una pausa de 2-3 segundos en el fondo sin perder tensión.'),
(9,4,'Empuja el suelo explosivamente para subir.'),
(9,5,'Bloquea cadera y rodillas arriba.'),

(10,1,'Colócate en la máquina hack con la espalda apoyada en el respaldo y hombros bajo las almohadillas.'),
(10,2,'Coloca los pies al ancho de hombros en la plataforma.'),
(10,3,'Desbloquea la máquina y desciende con control.'),
(10,4,'Alcanza flexión completa de rodillas.'),
(10,5,'Empuja la plataforma extendiendo rodillas sin bloquearlas por completo.'),

(11,1,'Siéntate en la máquina con la espalda completamente apoyada.'),
(11,2,'Coloca los pies en la plataforma al ancho de hombros.'),
(11,3,'Desbloquea los seguros y desciende con control.'),
(11,4,'Flexiona rodillas hasta 90° o algo más si tu movilidad lo permite sin curvar la zona lumbar.'),
(11,5,'Empuja la plataforma extendiendo rodillas sin bloquearlas.'),

(12,1,'Colócate bajo la barra del Smith con la barra sobre el trapecio.'),
(12,2,'Rota la barra para desbloquearla y adopta stance al ancho de hombros.'),
(12,3,'Desciende con control hasta profundidad completa.'),
(12,4,'Empuja hacia arriba manteniendo tensión en la cadena posterior.'),

(13,1,'Párate sobre una pierna con la otra extendida al frente.'),
(13,2,'Extiende los brazos al frente para contrapeso.'),
(13,3,'Desciende flexionando la cadera y rodilla de la pierna de apoyo.'),
(13,4,'Alcanza el fondo con el glúteo cerca del talón.'),
(13,5,'Empuja el suelo para volver a la posición de pie.'),
(13,6,'Mantén la pierna libre elevada durante todo el movimiento.'),

(14,1,'Adopta una posición de zancada con una pierna adelantada y otra atrasada.'),
(14,2,'Sujeta mancuernas a los lados.'),
(14,3,'Desciende flexionando la rodilla delantera hasta que el muslo quede paralelo al suelo.'),
(14,4,'Empuja el suelo con el talón delantero para volver a la posición inicial.'),
(14,5,'Completa las repeticiones y cambia de pierna.'),

(15,1,'Párate erguido con mancuernas a los lados o una barra sobre el trapecio.'),
(15,2,'Da un paso hacia adelante con una pierna.'),
(15,3,'Desciende flexionando ambas rodillas hasta que la rodilla trasera casi toque el suelo.'),
(15,4,'Empuja con la pierna delantera para volver a la posición inicial.'),
(15,5,'Alterna la pierna en cada repetición.'),

(16,1,'Comienza de pie con mancuernas a los lados.'),
(16,2,'Da un paso amplio hacia adelante con una pierna.'),
(16,3,'Desciende hasta que la rodilla trasera casi toque el suelo.'),
(16,4,'Empuja con la pierna delantera y adelanta la pierna trasera para dar el siguiente paso.'),
(16,5,'Continúa avanzando alternando piernas.'),

(17,1,'Párate erguido con mancuernas o barra.'),
(17,2,'Da un paso amplio hacia atrás con una pierna.'),
(17,3,'Desciende flexionando ambas rodillas hasta que la rodilla trasera casi toque el suelo.'),
(17,4,'Empuja con la pierna delantera para volver a la posición inicial.'),
(17,5,'Alterna la pierna en cada repetición.'),

(18,1,'Coloca un cajón robusto frente a ti.'),
(18,2,'Sujeta mancuernas a los lados.'),
(18,3,'Sube una pierna al cajón apoyando el pie completo.'),
(18,4,'Empuja con el talón para subir el cuerpo al cajón sin impulsarte con la pierna trasera.'),
(18,5,'Desciende con control regresando la pierna al suelo.'),

(19,1,'Colócate frente a la barra con los pies al ancho de caderas y la barra sobre el punto medio del pie.'),
(19,2,'Flexiona cadera y rodillas para tomar la barra con agarre pronado o mixto.'),
(19,3,'Baja las caderas hasta que las escápulas queden verticalmente alineadas sobre la barra.'),
(19,4,'Presuriza el core, contrae el dorsal y bloquea la espalda en posición neutra.'),
(19,5,'Empuja el suelo con las piernas manteniendo la barra pegada al cuerpo.'),
(19,6,'Cuando la barra supere las rodillas, extiende la cadera para completar el bloqueo.'),
(19,7,'Desciende invirtiendo el movimiento con control.'),

(20,1,'Adopta stance amplio con puntas rotadas hacia fuera y toma la barra por dentro de las rodillas.'),
(20,2,'Baja las caderas manteniendo el torso más vertical que en el convencional.'),
(20,3,'Presuriza el core y bloquea la espalda.'),
(20,4,'Empuja el suelo separando activamente las rodillas hacia fuera.'),
(20,5,'Bloquea cadera y rodillas simultáneamente al finalizar.'),
(20,6,'Desciende con control siguiendo la misma trayectoria.'),

(21,1,'Sostén la barra frente a los muslos con agarre pronado al ancho de hombros.'),
(21,2,'Flexiona ligeramente las rodillas y mantenlas fijas durante el movimiento.'),
(21,3,'Empuja las caderas hacia atrás bajando la barra pegada a las piernas.'),
(21,4,'Desciende hasta sentir estiramiento en los isquiotibiales (habitualmente por debajo de las rodillas).'),
(21,5,'Extiende la cadera contrayendo glúteos e isquios para volver a la posición inicial.'),

(22,1,'Sostén mancuernas al frente de los muslos con palmas hacia el cuerpo.'),
(22,2,'Flexiona ligeramente las rodillas y mantenlas fijas.'),
(22,3,'Empuja las caderas hacia atrás bajando las mancuernas cerca de las piernas.'),
(22,4,'Desciende hasta sentir estiramiento en isquios.'),
(22,5,'Extiende la cadera contrayendo glúteos para volver arriba.'),

(23,1,'Colócate sobre una plataforma de 2-5 cm para aumentar el recorrido.'),
(23,2,'Toma la barra con la técnica de peso muerto convencional.'),
(23,3,'Presuriza el core y bloquea la espalda antes de iniciar el tirón.'),
(23,4,'Empuja el suelo manteniendo la barra pegada al cuerpo.'),
(23,5,'Extiende cadera y rodillas hasta el bloqueo.'),
(23,6,'Desciende con control sin permitir que la espalda se redondee.'),

(24,1,'Coloca la barra sobre bloques a la altura deseada (bajo rodilla o sobre rodilla).'),
(24,2,'Adopta posición de peso muerto y toma la barra.'),
(24,3,'Presuriza el core y bloquea la espalda.'),
(24,4,'Empuja el suelo y extiende la cadera para bloquear arriba.'),
(24,5,'Desciende con control regresando a los bloques.'),

(25,1,'Colócate dentro de la trap bar con los pies al ancho de caderas.'),
(25,2,'Flexiona cadera y rodillas para tomar las asas neutras.'),
(25,3,'Presuriza el core y bloquea la espalda.'),
(25,4,'Empuja el suelo extendiendo cadera y rodillas simultáneamente.'),
(25,5,'Bloquea cadera al final y desciende con control.'),

(26,1,'Toma la barra con agarre pronado al ancho de hombros.'),
(26,2,'Mantén una flexión mínima en rodillas fija durante toda la serie.'),
(26,3,'Empuja las caderas hacia atrás bajando la barra pegada a las piernas.'),
(26,4,'Desciende con la espalda neutra hasta el rango que permita tu movilidad.'),
(26,5,'Extiende la cadera para volver a la posición inicial.'),

(27,1,'Párate sobre una pierna sosteniendo una mancuerna en la mano contraria.'),
(27,2,'Empuja la cadera hacia atrás manteniendo la pierna libre alineada con el torso.'),
(27,3,'Desciende hasta sentir estiramiento en el isquiotibial de la pierna de apoyo.'),
(27,4,'Extiende la cadera para volver a la posición de pie.'),
(27,5,'Completa todas las repeticiones antes de cambiar de pierna.'),

(28,1,'Coloca la barra en soportes del rack por encima de las rodillas.'),
(28,2,'Toma la barra con agarre pronado al ancho de hombros.'),
(28,3,'Presuriza el core y contrae el dorsal.'),
(28,4,'Extiende cadera y rodillas hasta el bloqueo.'),
(28,5,'Desciende con control regresando la barra a los soportes.'),

(29,1,'Coloca la barra sobre el trapecio como en la sentadilla.'),
(29,2,'Adopta stance al ancho de caderas con rodillas ligeramente flexionadas.'),
(29,3,'Empuja las caderas hacia atrás inclinando el torso hacia delante.'),
(29,4,'Desciende hasta que el torso quede casi paralelo al suelo.'),
(29,5,'Extiende la cadera para volver a la posición vertical.'),

(30,1,'Apoya la espalda alta contra un banco a la altura de las escápulas.'),
(30,2,'Coloca la barra sobre la cadera con una almohadilla protectora.'),
(30,3,'Planta los pies firmemente al ancho de hombros con las rodillas a 90°.'),
(30,4,'Empuja las caderas hacia arriba contrayendo los glúteos.'),
(30,5,'Alcanza la extensión completa alineando hombros, cadera y rodillas.'),
(30,6,'Desciende con control hasta casi tocar el suelo.'),

(31,1,'Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.'),
(31,2,'Coloca los brazos a los lados con las palmas hacia abajo.'),
(31,3,'Empuja las caderas hacia arriba contrayendo los glúteos.'),
(31,4,'Alcanza una línea recta entre hombros y rodillas.'),
(31,5,'Desciende con control sin apoyar completamente el glúteo entre repeticiones.'),

(32,1,'Túmbate en el banco con los ojos bajo la barra y los pies firmes en el suelo.'),
(32,2,'Toma la barra con agarre ligeramente más ancho que los hombros.'),
(32,3,'Retrae y deprime las escápulas creando un ligero arco lumbar.'),
(32,4,'Desmonta la barra y llévala sobre los hombros.'),
(32,5,'Inhala y baja la barra con control hasta tocar el esternón inferior.'),
(32,6,'Empuja la barra en línea recta manteniendo los codos a ~45-60°.'),
(32,7,'Exhala al superar el sticking point y bloquea codos arriba.'),

(33,1,'Configura el banco entre 30 y 45 grados de inclinación.'),
(33,2,'Toma la barra con agarre ligeramente más ancho que los hombros.'),
(33,3,'Retrae escápulas y desmonta la barra.'),
(33,4,'Baja la barra con control hasta la parte alta del pectoral.'),
(33,5,'Empuja la barra hacia arriba extendiendo los codos.'),
(33,6,'Mantén los codos a ~45-60° del torso durante todo el recorrido.'),

(34,1,'Configura el banco en declinación 15-30° y asegura las piernas.'),
(34,2,'Toma la barra con agarre similar al press banca plano.'),
(34,3,'Desmonta y baja la barra hasta la parte baja del pectoral.'),
(34,4,'Empuja la barra hasta la extensión de codos.'),
(34,5,'Controla la bajada evitando rebotes en el pecho.'),

(35,1,'Túmbate en el banco y toma la barra con agarre al ancho de los hombros.'),
(35,2,'Retrae escápulas y desmonta la barra.'),
(35,3,'Baja la barra al esternón manteniendo los codos cerca del torso.'),
(35,4,'Empuja la barra extendiendo los codos.'),
(35,5,'Bloquea codos arriba sin perder la retracción escapular.'),

(36,1,'Configura el press banca con retracción escapular y arco firmes.'),
(36,2,'Desmonta la barra y baja con control hasta el pecho.'),
(36,3,'Mantén la barra en contacto con el pecho durante 1-3 segundos sin perder tensión.'),
(36,4,'Empuja explosivamente hasta el bloqueo.'),
(36,5,'Devuelve la barra al rack al finalizar la serie.'),

(37,1,'Siéntate en un banco plano con una mancuerna sobre cada muslo.'),
(37,2,'Túmbate llevando las mancuernas al pecho con movimiento controlado de las rodillas.'),
(37,3,'Coloca las mancuernas a la altura del pecho con las palmas hacia los pies.'),
(37,4,'Empuja las mancuernas hacia arriba hasta la extensión de codos.'),
(37,5,'Baja con control hasta que las mancuernas queden a la altura del pecho.'),

(38,1,'Configura un banco entre 30-45 grados.'),
(38,2,'Siéntate y coloca las mancuernas sobre los muslos.'),
(38,3,'Túmbate llevando las mancuernas a la posición inicial junto al pecho superior.'),
(38,4,'Empuja las mancuernas hacia arriba extendiendo los codos.'),
(38,5,'Baja con control hasta la parte superior del pecho.'),

(39,1,'Túmbate en banco plano con una mancuerna en cada mano.'),
(39,2,'Extiende los brazos sobre el pecho con codos ligeramente flexionados.'),
(39,3,'Baja las mancuernas describiendo un arco amplio hacia los lados.'),
(39,4,'Desciende hasta sentir estiramiento en el pectoral sin perder la flexión de codos.'),
(39,5,'Contrae el pectoral para volver a la posición inicial.'),

(40,1,'Configura las poleas altas con agarres individuales.'),
(40,2,'Da un paso adelante y sujeta los agarres con brazos abiertos y codos ligeramente flexionados.'),
(40,3,'Cruza las manos frente al cuerpo contrayendo el pectoral.'),
(40,4,'Regresa a la posición inicial con control sin perder tensión.'),
(40,5,'Mantén los codos fijos durante todo el recorrido.'),

(41,1,'Sube a las paralelas con los brazos extendidos y hombros deprimidos.'),
(41,2,'Inclina ligeramente el torso hacia delante para enfatizar pectoral.'),
(41,3,'Desciende flexionando los codos hasta que los hombros queden a la altura de los codos.'),
(41,4,'Empuja hacia arriba extendiendo los codos.'),
(41,5,'Bloquea arriba sin encoger los hombros.'),

(42,1,'Colócate en posición de plancha con manos algo más anchas que los hombros.'),
(42,2,'Alinea cabeza, hombros, cadera y talones.'),
(42,3,'Baja el pecho al suelo con codos a ~45° del torso.'),
(42,4,'Empuja el suelo extendiendo los codos sin dejar caer la cadera.'),
(42,5,'Mantén el core activo durante toda la repetición.'),

(43,1,'Colócate en posición de plancha con las manos juntas formando un diamante bajo el pecho.'),
(43,2,'Alinea cabeza, cadera y talones.'),
(43,3,'Desciende manteniendo los codos cerca del torso.'),
(43,4,'Empuja el suelo extendiendo los codos.'),
(43,5,'Mantén la cadera firme sin dejarla caer.'),

(44,1,'Coloca la barra sobre las clavículas con agarre ligeramente más ancho que los hombros.'),
(44,2,'Adopta stance al ancho de caderas y presuriza el core.'),
(44,3,'Contrae glúteos y bloquea las piernas para evitar impulso.'),
(44,4,'Empuja la barra sobre la cabeza pasando por delante de la cara.'),
(44,5,'Cuando la barra supere la frente, mete la cabeza para alinear la barra con el punto medio del pie.'),
(44,6,'Bloquea la barra con codos totalmente extendidos.'),
(44,7,'Baja con control a la posición inicial.'),

(45,1,'Coloca la barra en rack frontal sobre los deltoides.'),
(45,2,'Adopta stance al ancho de caderas y presuriza el core.'),
(45,3,'Realiza un dip corto flexionando ligeramente rodillas y cadera.'),
(45,4,'Impulsa la barra hacia arriba extendiendo las piernas explosivamente.'),
(45,5,'Termina con los brazos empujando la barra a la posición overhead.'),
(45,6,'Bloquea los codos con la barra alineada sobre el punto medio del pie.'),
(45,7,'Desciende con control a la posición de rack.'),

(46,1,'Coloca la barra en rack frontal sobre los deltoides.'),
(46,2,'Realiza un dip vertical corto sin llevar la cadera atrás.'),
(46,3,'Impulsa la barra explosivamente extendiendo caderas y rodillas.'),
(46,4,'Ejecuta un segundo dip para recibir la barra en cuarto de sentadilla.'),
(46,5,'Bloquea los codos con la barra sobre la coronilla.'),
(46,6,'Extiende las piernas para quedar de pie con la barra overhead.'),
(46,7,'Desciende la barra al rack frontal con control.'),

(47,1,'Coloca la barra en rack frontal.'),
(47,2,'Ejecuta un dip vertical corto.'),
(47,3,'Impulsa la barra explosivamente hacia arriba.'),
(47,4,'Separa los pies en tijera adelantando una pierna y atrasando la otra.'),
(47,5,'Recibe la barra con los brazos bloqueados sobre la coronilla.'),
(47,6,'Recupera la posición trayendo primero el pie delantero y luego el trasero.'),
(47,7,'Desciende la barra al rack frontal con control.'),

(48,1,'Sujeta dos mancuernas frente al pecho con palmas hacia el cuerpo (supinación).'),
(48,2,'Presuriza el core y contrae los glúteos.'),
(48,3,'Rota las palmas hacia fuera mientras empujas las mancuernas hacia arriba.'),
(48,4,'Bloquea los codos con las palmas apuntando al frente.'),
(48,5,'Invierte la rotación al bajar hasta la posición inicial.'),

(49,1,'Párate erguido con una mancuerna en cada mano a los lados.'),
(49,2,'Flexiona ligeramente los codos y mantén las escápulas deprimidas.'),
(49,3,'Eleva las mancuernas lateralmente liderando con los codos.'),
(49,4,'Sube hasta que los brazos queden a la altura de los hombros.'),
(49,5,'Baja con control resistiendo la excéntrica.'),

(50,1,'Párate erguido con una mancuerna en cada mano frente a los muslos.'),
(50,2,'Presuriza el core y mantén los brazos casi extendidos.'),
(50,3,'Eleva las mancuernas al frente hasta la altura de los hombros.'),
(50,4,'Mantén una breve pausa arriba.'),
(50,5,'Desciende con control a la posición inicial.');


