(4,2,'Talones despegados','Levantar los talones por falta de movilidad.'),
(4,3,'Codos caídos','Dejar que los codos apunten al suelo.'),
(5,1,'Barra desalineada','Permitir que la barra se adelante fuera del punto medio del pie.'),
(5,2,'Codos flexionados','Perder el bloqueo overhead durante la subida.'),
(5,3,'Torso inclinado','Inclinar el torso hacia adelante rompiendo la línea vertical.'),
(6,1,'Codos caídos','Bajar los codos y dejar que la barra ruede hacia adelante.'),
(6,2,'Perder tensión lumbar','Redondear la zona lumbar en el fondo.'),
(7,1,'Rodillas colapsadas','Rodillas hacia dentro en la subida.'),
(7,2,'Puntas y rodillas desalineadas','Rodillas fuera de línea con las puntas de los pies.'),
(8,1,'Rebote en el cajón','Rebotar en el cajón perdiendo tensión.'),
(8,2,'Cargar el peso en la lumbar','Relajar el core al sentarse.'),
(9,1,'Perder tensión en pausa','Relajar la musculatura durante la pausa.'),
(9,2,'Elevar cadera primero','Subir la cadera antes que el pecho generando good morning.'),
(10,1,'Espalda despegada','Despegar la espalda del respaldo curvando la lumbar.'),
(10,2,'Rodillas hacia dentro','Colapso de rodillas en la subida.'),
(11,1,'Curvar la lumbar','Redondear la zona lumbar en el fondo del recorrido.'),
(11,2,'Rango parcial','Realizar rango muy corto sin trabajar la musculatura.'),
(11,3,'Rodillas bloqueadas','Bloquear las rodillas en cada repetición.'),
(12,1,'Confiar en la barra','Relajar el core por la estabilización externa.'),
(12,2,'Pies mal colocados','Pies muy adelantados o retrasados generando cizalla.'),
(13,1,'Talón despegado','Perder apoyo del talón por falta de movilidad.'),
(13,2,'Rodilla en valgo','Colapso de rodilla hacia dentro.'),
(13,3,'Espalda redondeada','Curvar la espalda en el fondo.'),
(14,1,'Rodilla adelantada excesivamente','Rodilla sobrepasando mucho la punta del pie.'),
(14,2,'Torso muy inclinado','Perder verticalidad del torso.'),
(15,1,'Paso demasiado corto','Sobrecarga en la rodilla delantera.'),
(15,2,'Rodilla en valgo','Colapso hacia dentro de la rodilla delantera.'),
(15,3,'Empujar con la pierna trasera','Perder trabajo unilateral.'),
(16,1,'Zancadas muy cortas','Reducir el trabajo de glúteo.'),
(16,2,'Rebotar el paso','Impulsarse con rebote de la rodilla trasera.'),
(17,1,'Torso caído','Inclinar el torso demasiado hacia delante.'),
(17,2,'Paso corto','Zancada demasiado corta.'),
(18,1,'Impulsarse con la pierna trasera','Empujar desde el suelo con la pierna trasera.'),
(18,2,'Cajón demasiado alto','Usar altura mayor a la que permite la movilidad.'),
(19,1,'Espalda redondeada','Curvar la lumbar durante el tirón.'),
(19,2,'Barra alejada del cuerpo','Permitir que la barra se separe de las piernas.'),
(19,3,'Cadera sube primero','Elevar la cadera antes que el pecho (stripper deadlift).'),
(19,4,'Hiperextensión final','Hiperextender la lumbar en el bloqueo.'),
(20,1,'Cadera muy alta','Iniciar con cadera excesivamente alta cerca de un peso muerto rumano.'),
(20,2,'Rodillas colapsadas','Rodillas hacia dentro en el tirón.'),
(20,3,'Barra alejada','Barra separada del cuerpo.'),
(21,1,'Curvar la espalda','Redondear la zona lumbar por bajar demasiado.'),
(21,2,'Flexionar rodillas','Convertir el RDL en peso muerto flexionando rodillas.'),
(21,3,'Barra separada','Alejar la barra de las piernas.'),
(22,1,'Espalda redondeada','Perder neutralidad lumbar en el descenso.'),
(22,2,'Mancuernas separadas','Permitir que las mancuernas se alejen del cuerpo.'),
(23,1,'Espalda redondeada','Curvar la lumbar por aumento de rango.'),
(23,2,'Cadera muy alta','Salir con cadera alta como en peso muerto rumano.'),
(24,1,'Hiperextender','Hiperextender la lumbar arriba.'),
(24,2,'Cargar en exceso','Usar peso que impide mantener espalda neutra.'),
(25,1,'Cadera alta','Iniciar con cadera demasiado alta.'),
(25,2,'Espalda curvada','Perder la posición neutra en la salida.'),
(26,1,'Flexionar rodillas','Excesiva flexión de rodilla.'),
(26,2,'Espalda redondeada','Perder tensión lumbar.'),
(27,1,'Cadera abierta','Rotar la cadera de la pierna libre hacia fuera.'),
(27,2,'Rodilla en valgo','Colapso interno de la rodilla de apoyo.'),
(28,1,'Hiperextender','Hiperextender lumbar en el bloqueo.'),
(28,2,'Impulso de rebote','Rebotar en los soportes.'),
(29,1,'Curvar la espalda','Redondear la lumbar durante el descenso.'),
(29,2,'Flexionar rodillas','Flexionar rodillas convirtiendo en sentadilla.'),
(30,1,'Hiperextender lumbar','Extender arriba desde la lumbar y no desde la cadera.'),
(30,2,'Rango corto','No alcanzar extensión completa de cadera.'),
(30,3,'Pies mal colocados','Pies muy adelantados o retrasados alterando el reclutamiento.'),
(31,1,'Empujar con lumbar','Extender arriba con la lumbar.'),
(31,2,'Rango corto','No alcanzar extensión completa de cadera.'),
(32,1,'Perder retracción escapular','Adelantar los hombros durante la subida.'),
(32,2,'Rebotar la barra','Rebotar la barra en el pecho.'),
(32,3,'Elevar los glúteos','Despegar los glúteos del banco durante el press.'),
(32,4,'Codos abiertos 90°','Abrir codos a 90° del torso aumentando riesgo de hombro.'),
(33,1,'Inclinación excesiva','Inclinación mayor a 45° convirtiéndolo en press militar.'),
(33,2,'Bajar la barra al pecho medio','Bajar a la posición del press plano en vez del pectoral superior.'),
(34,1,'Rango muy corto','Realizar rango parcial.'),
(34,2,'Rebotar la barra','Rebotar en el pecho por la ventaja mecánica.'),
(35,1,'Codos muy pegados','Pegar codos al torso comprimiendo articulación.'),
(35,2,'Rango parcial','No tocar el pecho.'),
(36,1,'Perder tensión','Relajar músculos durante la pausa.'),
(36,2,'Pausa demasiado corta','No mantener el tiempo de pausa completo.'),
(37,1,'Codos abiertos','Abrir demasiado los codos.'),
(37,2,'Descenso descontrolado','Bajar sin control.'),
(38,1,'Inclinación excesiva','Banco demasiado inclinado convirtiéndolo en press militar.'),
(38,2,'Rango corto','No bajar mancuernas al nivel del pectoral superior.'),
(39,1,'Codos rígidos','Extender demasiado los codos convirtiendo el ejercicio en press.'),
(39,2,'Bajar demasiado','Excesiva profundidad estresando el hombro.'),
(40,1,'Codos flexionados en exceso','Convertir el ejercicio en un press.'),
(40,2,'Cuerpo inestable','Falta de estabilidad postural.'),
(41,1,'Hombros encogidos','Elevar los hombros hacia las orejas.'),
(41,2,'Rango parcial','No bajar hasta que hombros queden a la altura de los codos.'),
(41,3,'Balanceo','Balancear el cuerpo para completar la repetición.'),
(42,1,'Cadera caída','Dejar caer la cadera.'),
(42,2,'Cabeza adelantada','Adelantar la cabeza rompiendo la línea neutra.'),
(42,3,'Codos abiertos 90°','Codos abiertos a 90° del torso.'),
(43,1,'Muñecas dolorosas','Sobrecarga en muñecas por posición forzada.'),
(43,2,'Codos abiertos','Abrir codos alejándolos del torso.'),
(44,1,'Hiperextender lumbar','Compensar con hiperextensión lumbar.'),
(44,2,'Impulso de piernas','Usar impulso de piernas en un press estricto.'),
(44,3,'No pasar la cabeza','No adelantar la cabeza al superar la barra generando trayectoria adelantada.'),
(45,1,'Dip largo','Realizar dip demasiado profundo (sentadilla).'),
(45,2,'Adelantar la cadera','Llevar la cadera hacia delante en el dip.'),
(46,1,'Recepción alta','Recibir con brazos flexionados y sin dip de recepción.'),
(46,2,'Dip con cadera atrás','Llevar la cadera atrás en el dip.'),
(47,1,'Tijera desalineada','Pie delantero desviado o trasero sin apoyo firme.'),
(47,2,'Recepción alta','No hundirse en la tijera durante la recepción.'),
(47,3,'Barra adelantada','Recibir la barra por delante de la coronilla.'),
(48,1,'Rotación incompleta','No completar la rotación desde supinación a pronación.'),
(48,2,'Trayectoria descuidada','Golpear la barbilla al rotar.'),
(49,1,'Impulso de tronco','Balancear el torso para elevar las mancuernas.'),
(49,2,'Elevar por encima del hombro','Subir más allá de la horizontal comprimiendo el manguito.'),
(50,1,'Impulso de espalda','Extender la espalda para elevar las mancuernas.'),
(50,2,'Rango excesivo','Elevar por encima del nivel de los hombros.');


-- ---------- ejercicio_consejos ----------
INSERT INTO ejercicio_consejos (ejercicio_id, orden, titulo, descripcion) VALUES
(1,1,'Bracing efectivo','Realiza una inhalación profunda y presuriza el abdomen 360° antes de descender.'),
(1,2,'Empuja el suelo','Piensa en separar el suelo con los pies para activar la cadena externa de cadera.'),
(1,3,'Trayectoria de la barra','La barra debe permanecer sobre el punto medio del pie durante todo el recorrido.'),
(1,4,'Elige la variante','Elige high-bar para más énfasis en cuádriceps y low-bar para cadena posterior.'),
(2,1,'Codos altos','Piensa en mostrar los codos a alguien enfrente para mantener el rack estable.'),
(2,2,'Torso vertical','Mantén el pecho arriba durante todo el recorrido.'),
(2,3,'Movilidad de muñeca','Trabaja movilidad de muñeca y tríceps para un rack sólido.'),
(3,1,'Distancia adecuada','Coloca la pierna delantera lo suficientemente adelantada para que la tibia quede vertical en el fondo.'),
(3,2,'Trabajo unilateral','Aprovecha para corregir asimetrías empezando por la pierna débil.'),
(3,3,'Estabilidad','Cuanto más se apoye el pie trasero de forma pasiva, más trabajará la pierna delantera.'),
(4,1,'Codos verticales','Mantén los codos apuntando hacia abajo entre las rodillas.'),
(4,2,'Progresión ideal','Usa esta variante como aprendizaje del patrón antes de cargar con barra.'),
(5,1,'Activación de dorsal','Activa el dorsal para estabilizar la barra overhead.'),
(5,2,'Movilidad indispensable','Trabaja movilidad torácica y de hombro antes de cargar peso.'),
(6,1,'Protección de codos','Usa mangas o toalla para amortiguar el contacto de la barra.'),
(6,2,'Torso vertical','Aprovecha la posición para mantener el torso muy erguido.'),
(7,1,'Rotar puntas','Ajusta la rotación de las puntas para permitir que las rodillas viajen sobre ellas.'),
(7,2,'Estimulación de aductores','Excelente estímulo para aductores y glúteo medio.'),
(8,1,'Altura del cajón','Elige una altura que te permita alcanzar profundidad completa.'),
(8,2,'Tensión sobre el cajón','Mantén tensión en la pausa para desarrollar fuerza de salida.'),
(9,1,'Pausa útil','La pausa elimina el reflejo miotático y desarrolla fuerza en el fondo.'),
(9,2,'Cuenta consistente','Utiliza una cuenta mental fija para mantener la duración de la pausa.'),
(10,1,'Colocación de pies','Adelantar los pies enfatiza glúteos e isquios.'),
(10,2,'Control excéntrico','Aprovecha la trayectoria guiada para bajar de forma controlada.'),
(11,1,'Pies altos y anchos','Enfatiza glúteos e isquios.'),
(11,2,'Pies bajos y estrechos','Enfatiza cuádriceps.'),
(11,3,'Pelvis anclada','Evita que la pelvis se despegue del respaldo.'),
(12,1,'Uso auxiliar','Ideal como accesorio o para hipertrofia con control.'),
(12,2,'No sustituir la libre','No lo utilices como reemplazo total de la sentadilla con barra libre.'),
(13,1,'Progresiones','Utiliza sentadilla en cajón asistida antes de la pistol completa.'),
(13,2,'Contrapeso','Mantén los brazos al frente y una carga ligera para mejor balance.'),
(14,1,'Postura vertical','Mantén el torso lo más vertical posible.'),
(14,2,'Punto medio del pie','Empuja desde el mediopié delantero.'),
(15,1,'Distancia del paso','Da un paso lo suficientemente amplio para que la tibia delantera quede vertical.'),
(15,2,'Alterna piernas','Alterna piernas para mantener simetría.'),
(16,1,'Zancadas largas','Alarga las zancadas para reclutar glúteo.'),
(16,2,'Ritmo constante','Mantén un ritmo constante evitando rebotes.'),
(17,1,'Baja carga','Excelente variante para iniciados por menor demanda de estabilidad.'),
(17,2,'Torso erguido','Enfatiza glúteo manteniendo el torso más vertical que en la zancada frontal.'),
(18,1,'Empuje del talón','Empuja desde el talón de la pierna que sube.'),
(18,2,'Sin impulso trasero','Evita empujarte con la pierna trasera del suelo.'),
(19,1,'Estirar la barra','Piensa en "estirar" o "doblar" la barra para activar el dorsal.'),
(19,2,'Empujar el suelo','Piensa en empujar el suelo con las piernas en la primera fase.'),
(19,3,'Barra pegada','Mantén la barra en contacto con el cuerpo durante todo el recorrido.'),
(19,4,'Bloqueo con glúteo','Termina apretando los glúteos sin hiperextender.'),
(20,1,'Rodillas fuera','Empuja las rodillas hacia las puntas de los pies.'),
(20,2,'Cadera baja','Inicia con la cadera baja para mantener torso vertical.'),
(21,1,'Empuja las caderas','Piensa en golpear una pared con los glúteos.'),
(21,2,'Rango individual','El rango depende de la movilidad de tus isquios sin curvar la espalda.'),
(21,3,'Barra pegada','Mantén las mancuernas cerca del cuerpo.'),
(22,1,'Control excéntrico','Enfatiza la fase excéntrica para mayor hipertrofia de isquios.'),
(22,2,'Neutralidad lumbar','Prioriza la neutralidad lumbar sobre el rango.'),
(23,1,'Cargas moderadas','Reduce la carga respecto al convencional por el mayor rango.'),
(23,2,'Placa fija','Utiliza una plataforma estable y no discos sueltos.'),
(24,1,'Zonas débiles','Excelente para trabajar puntos débiles del bloqueo.'),
(24,2,'Ajuste de altura','Ajusta la altura de los bloques al eslabón que quieres reforzar.'),
(25,1,'Excelente iniciación','Ideal como progresión previa al peso muerto convencional.'),
(25,2,'Menor demanda técnica','Requiere menos movilidad de tobillo y cadera que la barra recta.'),
(26,1,'No confundir con RDL','La diferencia con el rumano es la mínima flexión de rodilla.'),
(26,2,'Cargas menores','Utiliza cargas más ligeras por el estrés en la cadena posterior.'),
(27,1,'Cadera cuadrada','Mantén la cadera perpendicular al suelo sin abrirla.'),
(27,2,'Pared imaginaria','Piensa en empujar una pared con el talón libre.'),
(28,1,'Trabajo de espalda alta','Excelente para desarrollar espalda alta y trapecio.'),
(28,2,'Cargas supramáximas','Permite manejar cargas mayores que el peso muerto completo.'),
(29,1,'Iniciar suave','Comienza con cargas ligeras para dominar el patrón.'),
(29,2,'Barra baja','Coloca la barra en posición low-bar para mayor palanca.'),
(30,1,'Contracción arriba','Aprieta fuerte los glúteos al alcanzar la cima.'),
(30,2,'Almohadilla obligatoria','Usa almohadilla para evitar lesiones en cadera.'),
(30,3,'Barbilla al pecho','Meter la barbilla al pecho arriba mejora el reclutamiento de glúteo.'),
(31,1,'Empujar desde talones','Empuja desde los talones para activar glúteo.'),
(31,2,'Contracción isométrica','Añade 1-2 segundos de contracción arriba.'),
(32,1,'Retracción escapular','Junta las escápulas creando una base sólida.'),
(32,2,'Pies en el suelo','Mantén los pies firmes empujando el suelo (leg drive).'),
(32,3,'Barra sobre el hombro','Al bloquear, la barra debe quedar sobre el hombro no sobre el pecho.'),
(32,4,'Trayectoria en J','La barra recorre una ligera J desde el esternón al hombro.'),
(33,1,'Ángulo óptimo','30-45° suele ser el mejor rango; ángulos mayores comprometen hombro.'),
(33,2,'Codos moderados','Mantén codos a ~45° del torso para proteger el manguito.'),
(34,1,'Aprovechar apalancamiento','La declinación permite cargas mayores.'),
(34,2,'Bajar controlado','Controla la excéntrica para maximizar estímulo.'),
(35,1,'Distancia entre índices','Mantén los índices a la anchura de los hombros o poco menos.'),
(35,2,'Foco tríceps','Ideal como accesorio para mejorar el bloqueo del press.'),
(36,1,'Fuerza en fondo','Desarrolla fuerza de arranque desde el pecho.'),
(36,2,'Pausa 1-3s','Utiliza 1-3 segundos según el objetivo de trabajo.'),
(37,1,'Recorrido más amplio','El press con mancuernas permite mayor rango.'),
(37,2,'Estabilidad exigente','Requiere más estabilidad que la barra.'),
(38,1,'Palmas neutras','Prueba con palmas neutras para reducir estrés en hombro.'),
(38,2,'Descenso profundo','Aprovecha el mayor rango que ofrece la mancuerna.'),
(39,1,'Codos fijos','Mantén el mismo ángulo de codo durante todo el recorrido.'),
(39,2,'Sensación de abrazo','Imagina que abrazas un tronco al subir.'),
(40,1,'Trayectoria en arco','Realiza un arco amplio sin doblar los codos.'),
(40,2,'Punto de cruce','Cruza ligeramente las manos frente al cuerpo para maximizar contracción.'),
(41,1,'Escápulas deprimidas','Mantén los hombros lejos de las orejas.'),
(41,2,'Peso corporal antes de cargar','Domina el peso corporal antes de añadir carga.'),
(41,3,'Torso vertical o inclinado','Torso vertical para tríceps; inclinado para pectoral.'),
(42,1,'Plancha activa','Trata cada flexión como una plancha en movimiento.'),
(42,2,'Manos rotadas','Rotar ligeramente las manos hacia fuera protege el hombro.'),
(43,1,'Base estrecha','Ideal para enfatizar tríceps.'),
(43,2,'Codos cerca','Mantén los codos rozando el torso.'),
(44,1,'Glúteos apretados','Aprieta glúteos y core para evitar hiperextensión lumbar.'),
(44,2,'Cabeza a través','Al superar la cabeza, empuja la cabeza a través de los brazos.'),
(44,3,'Barra sobre punto medio','Termina con la barra alineada sobre el punto medio del pie.'),
(45,1,'Dip vertical','Realiza el dip con torso vertical no como sentadilla.'),
(45,2,'Transferencia rápida','Transfiere la potencia de piernas a barra rápidamente.'),
(46,1,'Doble dip','Dominar el doble dip diferencia al push jerk del push press.'),
(46,2,'Recepción firme','Recibe con brazos totalmente bloqueados.'),
(47,1,'Tijera adecuada','Distribuye peso 60/40 entre pierna delantera y trasera.'),
(47,2,'Empeine trasero','Talón trasero elevado con empuje del empeine.'),
(47,3,'Recepción rápida','Recibe la barra sin flexionar codos.'),
(48,1,'Rotación controlada','Realiza la rotación de mancuernas de forma fluida.'),
(48,2,'Trayectoria segura','Aleja las mancuernas de la cara al rotar.'),
(49,1,'Lidera con codos','Piensa en llevar los codos hacia el techo.'),
(49,2,'Baja lenta','Controla la fase excéntrica para maximizar hipertrofia.'),
(50,1,'Alternar brazos','Alterna brazos si te falta estabilidad.'),
(50,2,'Foco en deltoides anterior','Mantén una ligera inclinación de la mano para enfatizar deltoides anterior.');


