-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(51,1,'Cuelga de la barra con agarre pronado algo más ancho que los hombros.'),
(51,2,'Activa las escápulas deprimiéndolas y retrayéndolas.'),
(51,3,'Tira del cuerpo hacia arriba llevando los codos hacia el suelo.'),
(51,4,'Sube hasta que la barbilla supere la barra.'),
(51,5,'Desciende con control hasta la suspensión completa.'),

(52,1,'Cuelga de la barra con agarre supinado al ancho de los hombros.'),
(52,2,'Activa escápulas y core.'),
(52,3,'Tira del cuerpo hacia arriba llevando el pecho hacia la barra.'),
(52,4,'Alcanza la barbilla por encima de la barra.'),
(52,5,'Desciende con control hasta la suspensión completa.'),

(53,1,'Cuelga con agarre neutro (palmas enfrentadas) al ancho de los hombros.'),
(53,2,'Deprime y retrae las escápulas.'),
(53,3,'Tira del pecho hacia la barra.'),
(53,4,'Supera la barbilla la barra y desciende con control.'),

(54,1,'Coloca la carga en un cinturón de lastre o entre los pies.'),
(54,2,'Cuelga con agarre pronado y activa escápulas.'),
(54,3,'Ejecuta una dominada estricta hasta que la barbilla supere la barra.'),
(54,4,'Baja con control resistiendo la excéntrica.'),

(55,1,'Coloca la banda en la barra formando un lazo.'),
(55,2,'Introduce un pie o rodilla en la banda para recibir asistencia.'),
(55,3,'Cuelga con agarre pronado y activa las escápulas.'),
(55,4,'Ejecuta la dominada aprovechando la asistencia.'),
(55,5,'Desciende con control.'),

(56,1,'Siéntate en la máquina con las rodillas fijas bajo el rodillo.'),
(56,2,'Toma la barra con agarre pronado más ancho que los hombros.'),
(56,3,'Deprime las escápulas y lleva la barra hacia la parte alta del pecho.'),
(56,4,'Regresa la barra a la posición inicial con control.'),

(57,1,'Coloca el agarre en V en la polea alta.'),
(57,2,'Siéntate y ajusta las rodillas bajo el rodillo.'),
(57,3,'Tira del agarre hacia la parte alta del pecho manteniendo torso vertical.'),
(57,4,'Regresa el agarre con control.'),

(58,1,'Coloca la barra en polea alta y tómala con agarre supinado al ancho de los hombros.'),
(58,2,'Siéntate ajustando las rodillas bajo el rodillo.'),
(58,3,'Tira de la barra hacia la parte alta del pecho.'),
(58,4,'Regresa la barra con control.'),

(59,1,'Colócate en posición de peso muerto y sostén la barra con agarre pronado.'),
(59,2,'Inclina el torso hasta ~45° manteniendo espalda neutra.'),
(59,3,'Presuriza el core y tira de la barra hacia el ombligo.'),
(59,4,'Aprieta las escápulas al final del recorrido.'),
(59,5,'Desciende la barra con control sin perder la posición del torso.'),

(60,1,'Coloca la barra en el suelo con los pies debajo de la barra.'),
(60,2,'Inclina el torso paralelo al suelo con la espalda neutra.'),
(60,3,'Explosivamente tira la barra hacia el esternón inferior.'),
(60,4,'Regresa la barra al suelo entre cada repetición sin arrastrar.'),
(60,5,'Reajusta el bracing antes del siguiente tirón.'),

(61,1,'Sujeta la barra con agarre supinado al ancho de los hombros.'),
(61,2,'Inclínate hacia adelante 20-30° con espalda neutra.'),
(61,3,'Tira la barra hacia la parte baja del abdomen.'),
(61,4,'Desciende con control.'),

(62,1,'Apoya una rodilla y una mano en el banco.'),
(62,2,'Sostén la mancuerna con el brazo libre extendido.'),
(62,3,'Tira de la mancuerna hacia la cadera manteniendo el codo cerca del torso.'),
(62,4,'Baja la mancuerna con control hasta la extensión.'),
(62,5,'Completa todas las repeticiones y cambia de lado.'),

(63,1,'Ancla un extremo de la barra en una esquina o landmine.'),
(63,2,'Coloca el agarre en V bajo la barra.'),
(63,3,'Inclínate hacia adelante con espalda neutra.'),
(63,4,'Tira del agarre hacia el pecho.'),
(63,5,'Regresa la barra con control.'),

(64,1,'Ajusta la máquina para que el agarre quede a la altura del esternón.'),
(64,2,'Apoya el pecho en el respaldo y sujeta los agarres.'),
(64,3,'Tira de los agarres hacia el torso apretando escápulas.'),
(64,4,'Regresa a la posición inicial con control.'),

(65,1,'Siéntate en la máquina y coloca los pies en los soportes con rodillas ligeramente flexionadas.'),
(65,2,'Toma el agarre en V manteniendo el torso vertical.'),
(65,3,'Tira del agarre hacia el abdomen inferior.'),
(65,4,'Aprieta las escápulas al final del recorrido.'),
(65,5,'Regresa el agarre con control sin flexionar el torso.'),

(66,1,'Coloca la barra en anclaje landmine y añade carga en un extremo.'),
(66,2,'Toma la barra con agarre neutro o accesorio en V.'),
(66,3,'Inclina el torso con la espalda neutra.'),
(66,4,'Tira de la barra hacia la cadera.'),
(66,5,'Baja con control regresando a la extensión.'),

(67,1,'Ajusta la polea a la altura de la cara con una cuerda.'),
(67,2,'Sujeta ambos extremos de la cuerda con agarre pronado.'),
(67,3,'Tira de la cuerda hacia la cara separando las manos y rotando externamente los hombros.'),
(67,4,'Mantén los codos altos durante todo el recorrido.'),
(67,5,'Regresa con control.'),

(68,1,'Túmbate en un banco plano perpendicular sosteniendo una mancuerna con ambas manos sobre el pecho.'),
(68,2,'Baja la mancuerna en arco por detrás de la cabeza con codos ligeramente flexionados.'),
(68,3,'Alcanza el estiramiento del dorsal.'),
(68,4,'Regresa la mancuerna al punto de partida contrayendo dorsal y pectoral.'),

(69,1,'Configura la polea alta con la barra recta.'),
(69,2,'Sujeta la barra con brazos casi extendidos.'),
(69,3,'Empuja la barra hacia los muslos manteniendo los codos casi bloqueados.'),
(69,4,'Regresa la barra hacia arriba resistiendo la excéntrica.'),

(70,1,'Cuelga de las anillas con agarre falso (muñecas por encima de las anillas).'),
(70,2,'Realiza un kip inicial impulsando cadera y hombros hacia adelante.'),
(70,3,'Tira explosivamente llevando las anillas al pecho.'),
(70,4,'Inclina el torso hacia adelante para transitar rápidamente al dip.'),
(70,5,'Empuja las anillas extendiendo los codos hasta bloquear arriba.'),
(70,6,'Desciende con control hasta la posición inicial.'),

(71,1,'Cuelga de la barra con agarre pronado.'),
(71,2,'Realiza un kip amplio impulsando cadera y hombros.'),
(71,3,'Tira explosivamente llevando las caderas hacia la barra.'),
(71,4,'Rebasa la barra en la transición con brazos empujando por encima.'),
(71,5,'Extiende los codos para bloquear el soporte.'),
(71,6,'Regresa a la suspensión con control.'),

(72,1,'Cuelga de la barra con agarre pronado.'),
(72,2,'Activa las escápulas y presuriza el core.'),
(72,3,'Tira del cuerpo hacia arriba hasta que el pecho toque la barra.'),
(72,4,'Desciende con control hasta la suspensión completa.'),

(73,1,'Cuelga de la barra con agarre pronado.'),
(73,2,'Alterna posiciones de arco y hueco impulsando cadera y hombros.'),
(73,3,'Aprovecha el impulso para tirar el pecho hacia la barra.'),
(73,4,'Desciende y encadena el siguiente kip sin pausa.'),

(74,1,'Cuelga con agarre pronado.'),
(74,2,'Inicia un kip amplio con arco pronunciado.'),
(74,3,'Realiza una trayectoria circular llevando el pecho por delante de la barra.'),
(74,4,'Rebota inmediatamente al siguiente ciclo sin pausa.'),

(75,1,'Cuelga de la barra con agarre pronado.'),
(75,2,'Inicia un kip para generar impulso.'),
(75,3,'Contrae el core y sube las piernas hacia la barra.'),
(75,4,'Toca con los pies el espacio entre las manos.'),
(75,5,'Desciende con control preparando el siguiente kip.'),

(76,1,'Cuelga de la barra con agarre pronado.'),
(76,2,'Genera un kip corto.'),
(76,3,'Lleva las rodillas hacia los codos flexionando la cadera.'),
(76,4,'Desciende con control.'),

(77,1,'Sujeta la cuerda con las manos por encima de la cabeza.'),
(77,2,'Sube una pierna y engancha la cuerda con el empeine y la parte externa del otro pie (J-hook).'),
(77,3,'Impúlsate extendiendo las piernas y sube las manos.'),
(77,4,'Vuelve a enganchar la cuerda con los pies y repite hasta llegar arriba.'),
(77,5,'Desciende de forma controlada alternando manos y pies.'),

(78,1,'Sostén la barra frente a los muslos con agarre pronado.'),
(78,2,'Adopta stance al ancho de caderas y presuriza el core.'),
(78,3,'Eleva los hombros hacia las orejas contrayendo el trapecio.'),
(78,4,'Mantén una pausa arriba.'),
(78,5,'Desciende con control.'),

(79,1,'Sostén mancuernas a los lados.'),
(79,2,'Eleva los hombros hacia las orejas.'),
(79,3,'Mantén una breve contracción arriba.'),
(79,4,'Desciende con control.'),

(80,1,'Toma dos mancuernas o handles pesados con agarre firme.'),
(80,2,'Adopta postura erguida con escápulas retraídas.'),
(80,3,'Camina a paso corto y estable durante la distancia programada.'),
(80,4,'Mantén el core activo y la respiración controlada.'),
(80,5,'Deposita las cargas con seguridad al terminar.'),

(81,1,'Coloca el yoke sobre el trapecio como en la sentadilla.'),
(81,2,'Extiende cadera y rodillas para levantar el yoke.'),
(81,3,'Camina con pasos cortos, torso vertical y core presurizado.'),
(81,4,'Deposita el yoke controlando el descenso.'),

(82,1,'Carga el sled con la resistencia deseada.'),
(82,2,'Sujeta los soportes con agarre firme y adopta posición inclinada hacia adelante.'),
(82,3,'Empuja el sled extendiendo activamente las piernas y transfiriendo peso a la pierna adelantada.'),
(82,4,'Da pasos cortos y potentes.'),
(82,5,'Mantén el core activo durante todo el recorrido.'),

(83,1,'Enganchate al sled mediante arnés o cuerda.'),
(83,2,'Inclínate hacia atrás contra la resistencia.'),
(83,3,'Camina con pasos cortos empujando el suelo con los talones.'),
(83,4,'Mantén el core activo y la espalda neutra.'),

(84,1,'Colócate frente a la piedra con los pies separados.'),
(84,2,'Abraza la piedra desde abajo con los antebrazos.'),
(84,3,'Levanta la piedra hasta el regazo con extensión de cadera.'),
(84,4,'Reajusta el agarre elevando el pecho contra la piedra.'),
(84,5,'Empuja las caderas hacia adelante y extiende para colocar la piedra sobre la plataforma.'),

(85,1,'Sitúa el log en el suelo y adopta posición de peso muerto.'),
(85,2,'Tira del log hasta el regazo (lap).'),
(85,3,'Rueda el log al pecho al tiempo que extiendes la cadera.'),
(85,4,'Presuriza el core y ejecuta un press desde el pecho hasta overhead.'),
(85,5,'Baja el log al pecho y regresa al suelo con control.'),

(86,1,'Colócate frente a la barra axle con stance convencional.'),
(86,2,'Toma la barra con agarre pronado o de gancho (hook grip).'),
(86,3,'Presuriza el core y bloquea la espalda.'),
(86,4,'Extiende cadera y rodillas hasta el bloqueo.'),
(86,5,'Desciende con control.'),

(87,1,'Coloca el sandbag frente a ti y abrázalo contra el pecho.'),
(87,2,'Extiende cadera y piernas para levantarlo.'),
(87,3,'Camina con pasos cortos manteniendo el sandbag firme contra el torso.'),
(87,4,'Deposita el sandbag con control al finalizar.'),

(88,1,'Adopta posición de peso muerto sobre el sandbag.'),
(88,2,'Levanta el sandbag hasta el regazo.'),
(88,3,'Impulsa con la cadera para llevarlo al hombro.'),
(88,4,'Deja caer el sandbag desde el hombro por el otro lado.'),

(89,1,'Adopta posición de peso muerto frente al sandbag.'),
(89,2,'Extiende cadera y piernas explosivamente.'),
(89,3,'Encoge los brazos alrededor del sandbag llevándolo al pecho.'),
(89,4,'Recupera de pie y baja el sandbag con control.'),

(90,1,'Colócate frente a la rueda con los pies separados y rodillas flexionadas.'),
(90,2,'Coloca las manos bajo la rueda con antebrazos pegados a ella.'),
(90,3,'Explosivamente extiende cadera y piernas para levantarla.'),
(90,4,'Cuando la rueda esté a la altura del pecho, empuja con las manos para voltearla.'),
(90,5,'Persigue el volteo dando un paso hacia adelante.'),

(91,1,'Toma la barra con agarre ancho y hook grip.'),
(91,2,'Adopta la posición de salida con escápulas sobre la barra.'),
(91,3,'Ejecuta el primer tirón extendiendo rodillas manteniendo el torso constante.'),
(91,4,'Al pasar las rodillas, extiende explosivamente cadera y rodillas (segundo tirón).'),
(91,5,'Encoge los hombros y flexiona los codos para pasar bajo la barra.'),
(91,6,'Recibe la barra overhead en sentadilla profunda con brazos bloqueados.'),
(91,7,'Levántate manteniendo la barra estable overhead.'),

(92,1,'Toma la barra con agarre ancho y hook grip.'),
(92,2,'Ejecuta el primer y segundo tirón como en el arranque.'),
(92,3,'Encoge y pasa bajo la barra recibiéndola con las caderas por encima del paralelo.'),
(92,4,'Estabiliza la barra overhead y levántate.'),

(93,1,'Toma la barra con agarre ancho e inicia de pie con la barra en suspensión sobre las rodillas.'),
(93,2,'Empuja las caderas atrás bajando la barra a la posición de suspensión.'),
(93,3,'Ejecuta el segundo tirón explosivamente.'),
(93,4,'Encoge y pasa bajo la barra recibiéndola overhead.'),
(93,5,'Estabiliza y levántate.'),

(94,1,'Toma la barra con agarre ancho y hook grip.'),
(94,2,'Ejecuta el primer y segundo tirón como en el arranque.'),
(94,3,'Sin pasar bajo la barra, empuja con brazos hasta la posición overhead.'),
(94,4,'Recibe con las piernas extendidas y brazos bloqueados.'),

(95,1,'Coloca la barra sobre el trapecio con agarre de arranque.'),
(95,2,'Empuja la barra explosivamente hacia arriba.'),
(95,3,'Simultáneamente pasa bajo la barra recibiéndola overhead en sentadilla profunda.'),
(95,4,'Levántate manteniendo la barra estable.'),

(96,1,'Toma la barra con el agarre ancho del arranque y hook grip.'),
(96,2,'Adopta posición de peso muerto y bloquea la espalda.'),
(96,3,'Empuja el suelo extendiendo cadera y rodillas.'),
(96,4,'Bloquea arriba con hombros por encima de la barra.'),
(96,5,'Desciende con control.'),

(97,1,'Adopta posición de arranque con agarre ancho.'),
(97,2,'Ejecuta el primer tirón manteniendo el torso.'),
(97,3,'Al pasar las rodillas ejecuta el segundo tirón explosivamente.'),
(97,4,'Termina en extensión completa sin encoger ni pasar bajo la barra.'),

(98,1,'Ejecuta el snatch pull hasta la extensión.'),
(98,2,'Continúa el tirón elevando la barra con los brazos hasta la altura del esternón.'),
(98,3,'Mantén los codos altos.'),
(98,4,'Desciende con control regresando a la posición inicial.'),

(99,1,'Toma la barra con agarre al ancho de los hombros y hook grip.'),
(99,2,'Adopta posición de salida con escápulas sobre la barra.'),
(99,3,'Ejecuta el primer tirón manteniendo el torso constante.'),
(99,4,'Al pasar la rodilla, extiende explosivamente cadera y rodillas.'),
(99,5,'Encoge y pasa bajo la barra recibiéndola en rack frontal en sentadilla profunda.'),
(99,6,'Levántate hasta la posición vertical con la barra en rack.'),

(100,1,'Toma la barra con agarre al ancho de los hombros y hook grip.'),
(100,2,'Ejecuta el primer y segundo tirón.'),
(100,3,'Encoge y pasa bajo la barra recibiéndola en rack frontal con caderas por encima del paralelo.'),
(100,4,'Levántate hasta la posición vertical.');


