-- ---------- ejercicio_consejos ----------
INSERT INTO ejercicio_consejos (ejercicio_id, orden, titulo, descripcion) VALUES
(51,1,'Deprimir escápulas primero','Inicia cada repetición activando escápulas antes de tirar.'),
(51,2,'Codos hacia atrás y abajo','Piensa en tirar los codos hacia los bolsillos traseros.'),
(51,3,'Cuerpo hueco','Mantén una posición hollow durante todo el recorrido.'),
(52,1,'Foco en bíceps','Ideal como accesorio pesado para bíceps.'),
(52,2,'Full ROM','Extiende completamente los brazos en cada repetición.'),
(53,1,'Amable con hombros','El agarre neutro suele ser el más cómodo para hombros.'),
(53,2,'Progresión','Ideal como progresión hacia la dominada pronada.'),
(54,1,'Progresión conservadora','Añade 2.5-5 kg por sesión para progresar de forma segura.'),
(54,2,'Rango completo','Prioriza rango completo sobre cargas altas.'),
(55,1,'Banda apropiada','Selecciona una banda que permita 5-8 reps con calidad.'),
(55,2,'Progresión','Reduce la banda progresivamente hasta la dominada estricta.'),
(56,1,'Alternativa a la dominada','Excelente sustituto mientras trabajas la dominada.'),
(56,2,'Barra al pecho','Trae la barra al pecho no al cuello.'),
(57,1,'Cómodo para hombros','El agarre neutro suele ser el más amable.'),
(57,2,'Foco en dorsal','Piensa en llevar los codos hacia los bolsillos.'),
(58,1,'Foco en dorsal inferior','Muy usado para desarrollar dorsal inferior.'),
(58,2,'Agarre estrecho','Prueba un agarre poco más ancho que los hombros.'),
(59,1,'Ángulo del torso','Cuanto más paralelo al suelo, más dorsal y menos trapecio.'),
(59,2,'Barra a la cadera','Tira la barra hacia la parte baja del abdomen para foco en dorsal.'),
(59,3,'Cinturón útil','Considera cinturón para cargas pesadas.'),
(60,1,'Descanso entre reps','Cada repetición inicia desde el suelo con reseteo del bracing.'),
(60,2,'Explosividad','Ejecuta el tirón explosivamente para máxima activación.'),
(61,1,'Cómodo lumbar','El ángulo más vertical reduce el estrés lumbar.'),
(61,2,'Foco en dorsal inferior','El agarre supinado enfatiza dorsal inferior y bíceps.'),
(62,1,'Rango completo','Aprovecha el gran rango que ofrece la mancuerna.'),
(62,2,'Contrae escápula','Enfatiza la contracción escapular al final.'),
(63,1,'Estabilidad lumbar','Mantén el core presurizado para proteger la lumbar.'),
(63,2,'Foco escapular','Retrae escápulas al final de cada tirón.'),
(64,1,'Ideal para principiantes','Excelente por su recorrido guiado y estabilidad.'),
(64,2,'Foco en el remo','Piensa en llevar los codos hacia atrás no en tirar con brazos.'),
(65,1,'Torso vertical','Mantén el torso vertical durante todo el recorrido para foco en dorsal.'),
(65,2,'Aprieta escápulas','Aprieta escápulas al final para maximizar la contracción.'),
(66,1,'Ángulo natural','El anclaje ofrece un patrón cómodo para el hombro.'),
(66,2,'Unilateral','Prueba versión unilateral para trabajar core anti-rotación.'),
(67,1,'Cargas ligeras','Trabaja con cargas moderadas priorizando forma.'),
(67,2,'Salud del hombro','Muy útil para salud del manguito rotador.'),
(67,3,'Rotar externamente','Piensa en abrir la cuerda al final del movimiento.'),
(68,1,'Estiramiento del dorsal','Aprovecha el estiramiento del dorsal en el fondo.'),
(68,2,'Cargas moderadas','No sobrecargues; prioriza forma y control.'),
(69,1,'Tensión constante','La polea mantiene tensión durante todo el recorrido.'),
(69,2,'Foco dorsal','Piensa en empujar la barra con los codos casi bloqueados.'),
(70,1,'Agarre falso indispensable','Practica el agarre falso antes de intentar el muscle-up.'),
(70,2,'Trabajar transitions','Practica transiciones asistidas con banda.'),
(70,3,'Fuerza previa','Domina 5-8 dominadas estrictas y 5-8 dips estrictos antes de intentarlo.'),
(71,1,'Kip agresivo','Un kip potente facilita mucho la transición.'),
(71,2,'Manos rápidas','Suelta y recoloca las manos rápido al superar la barra.'),
(72,1,'Retracción escapular','Retrae escápulas al iniciar el tirón.'),
(72,2,'Pecho hacia la barra','Piensa en llevar el pecho no la barbilla.'),
(73,1,'Practicar arco/hueco','Domina las posiciones estáticas antes del kipping completo.'),
(73,2,'Cadencia','Aprovecha el rebote entre repeticiones para mantener el ritmo.'),
(74,1,'Fluidez circular','Piensa en una trayectoria continua sin pausas.'),
(74,2,'Cadera hacia la barra','Lleva la cadera hacia la barra en cada ciclo.'),
(75,1,'Kip organizado','Practica kip antes de añadir el toes-to-bar.'),
(75,2,'Escápulas activas','Mantén las escápulas deprimidas durante todo el movimiento.'),
(76,1,'Progresión al T2B','Ideal como progresión para toes-to-bar.'),
(76,2,'Control','Prioriza control sobre velocidad.'),
(77,1,'Wrap con los pies','El J-hook es la técnica más eficiente para principiantes.'),
(77,2,'Descenso seguro','Baja lentamente para preservar los agarres.'),
(77,3,'Practica sin piernas','Trabaja legless rope climb como progresión avanzada.'),
(78,1,'Rango completo','Trabaja rango completo elevando lo más posible.'),
(78,2,'Ancla las escápulas','Cuidado con hipercargar el ejercicio y perder control.'),
(79,1,'Alcance mayor','Con mancuernas obtienes mayor recorrido que con barra.'),
(79,2,'Control excéntrico','Baja las mancuernas lentamente.'),
(80,1,'Grip robusto','Sujeta las asas con fuerza sin depender de cintas.'),
(80,2,'Respiración','Respira de forma controlada durante el paseo.'),
(80,3,'Pasos cortos','Mejor cortos y rápidos que largos e inestables.'),
(81,1,'Core presurizado','Mantén el bracing durante toda la distancia.'),
(81,2,'Pasos pequeños','Pasos cortos ayudan a mantener el yoke estable.'),
(82,1,'Pierna adelantada extendida','Extiende bien la pierna adelantada en cada paso.'),
(82,2,'Empuja el suelo','Piensa en empujar el suelo hacia atrás.'),
(83,1,'Inclinación adecuada','Ajusta la inclinación en función de la resistencia.'),
(83,2,'Pasos regulares','Mantén un ritmo constante.'),
(84,1,'Tacky o resina','Usa tacky para mejorar la fricción con la piedra.'),
(84,2,'Regazo obligatorio','Aprovecha la fase de regazo para reajustar.'),
(85,1,'Rack sólido','Mantén un rack firme en el pecho antes del press.'),
(85,2,'Cinturón','Utiliza cinturón para presuriza mejor.'),
(86,1,'Hook grip','Utiliza hook grip para no fallar en el agarre.'),
(86,2,'Grip trabajado','Excelente para desarrollar fuerza de agarre.'),
(87,1,'Abrazo firme','Aprieta el sandbag contra el pecho durante todo el paseo.'),
(87,2,'Postura neutra','Mantén la espalda neutra durante el transporte.'),
(88,1,'Cadera explosiva','Utiliza extensión explosiva de cadera para subir el sandbag.'),
(88,2,'Alterna hombros','Alterna hombros en cada repetición.'),
(89,1,'Extensión de cadera','Aprovecha la extensión de cadera para elevar el sandbag.'),
(89,2,'Codos altos','Termina con codos altos como en un clean.'),
(90,1,'Piernas primero','Extiende cadera y rodillas antes que la espalda.'),
(90,2,'Empuja con las manos','Al final del recorrido, empuja con las manos para voltearla.'),
(91,1,'Hook grip','Utiliza hook grip para no fallar en cargas altas.'),
(91,2,'Barra pegada','Mantén la barra cerca del cuerpo durante todo el recorrido.'),
(91,3,'Paciencia en el primer tirón','No aceleres el primer tirón; explota en el segundo.'),
(91,4,'Rebase agresivo','Encoge y pasa bajo la barra rápidamente.'),
(92,1,'Alta velocidad de barra','Requiere alta velocidad de tirón por menor rebase.'),
(92,2,'Barra pegada','Cuida la trayectoria de la barra.'),
(93,1,'Tensión constante','Mantén tensión en isquios y core durante el descenso.'),
(93,2,'Ideal para técnica','Ideal para trabajar el segundo tirón aisladamente.'),
(94,1,'Sin sentadilla','Ideal como accesorio para trabajar la extensión y el rack de brazos.'),
(94,2,'Cargas ligeras','Utiliza cargas moderadas.'),
(95,1,'Trabajo de recepción','Ideal para trabajar la posición de recepción del arranque.'),
(95,2,'Progresión gradual','Comienza con cargas ligeras hasta dominar la técnica.'),
(96,1,'Ideal para dorsal','Excelente para desarrollar dorsal y espalda alta.'),
(96,2,'Complementa el arranque','Herramienta esencial para halterofilia.'),
(97,1,'Extensión completa','Termina en triple extensión (tobillo, rodilla, cadera).'),
(97,2,'Foco potencia','Herramienta clave para desarrollar potencia del segundo tirón.'),
(98,1,'Codos por encima','Los codos deben terminar por encima de las manos.'),
(98,2,'Trabajo de tirón','Excelente para trabajar el tirón final del arranque.'),
(99,1,'Codos rápidos','Rota los codos rápidamente en el rack.'),
(99,2,'Rack sólido','Mantén el rack estable con codos altos.'),
(99,3,'Paciencia en el suelo','El primer tirón debe ser controlado.'),
(100,1,'Recepción alta','Recepción por encima del paralelo lo diferencia del clean completo.'),
(100,2,'Barra pegada','La barra debe permanecer cerca del cuerpo.');


