-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(101,1,'Sujeta la barra con agarre supinado al ancho de los hombros.'),
(101,2,'Mantén los codos pegados al torso y el core presurizado.'),
(101,3,'Flexiona los codos elevando la barra hacia los hombros.'),
(101,4,'Contrae el bíceps en la cima.'),
(101,5,'Desciende con control hasta la extensión completa.'),

(102,1,'Sujeta una mancuerna en cada mano con las palmas mirando al cuerpo.'),
(102,2,'Flexiona un codo rotando la palma hacia arriba (supinación).'),
(102,3,'Alcanza la contracción máxima con la palma hacia arriba.'),
(102,4,'Desciende con control invirtiendo la rotación.'),
(102,5,'Alterna los brazos o ejecuta simultáneamente.'),

(103,1,'Sujeta la barra Z con las manos en la parte ondulada más estrecha.'),
(103,2,'Mantén los codos pegados al torso.'),
(103,3,'Flexiona los codos elevando la barra.'),
(103,4,'Baja con control.'),

(104,1,'Sujeta las mancuernas con palmas enfrentadas al cuerpo (agarre neutro).'),
(104,2,'Flexiona los codos manteniendo el agarre neutro.'),
(104,3,'Sube hasta que la mancuerna esté cerca del hombro.'),
(104,4,'Desciende con control manteniendo el agarre neutro.'),

(105,1,'Siéntate en un banco con las piernas separadas.'),
(105,2,'Apoya el codo del brazo activo sobre el muslo interno.'),
(105,3,'Flexiona el codo elevando la mancuerna.'),
(105,4,'Contrae el bíceps arriba.'),
(105,5,'Desciende con control.'),

(106,1,'Coloca el banco predicador de forma que las axilas descansen sobre la almohadilla.'),
(106,2,'Sujeta la barra o mancuernas con agarre supinado.'),
(106,3,'Flexiona los codos elevando la carga.'),
(106,4,'Desciende con control sin extender completamente el codo.'),

(107,1,'Configura un banco inclinado a 45-60°.'),
(107,2,'Siéntate con mancuernas a los lados y palmas al frente.'),
(107,3,'Flexiona los codos elevando las mancuernas manteniendo los codos atrás.'),
(107,4,'Contrae arriba y desciende con control.'),

(108,1,'Ejecuta 7 curls parciales desde la extensión hasta la mitad del recorrido.'),
(108,2,'Ejecuta 7 curls parciales desde la mitad hasta la contracción máxima.'),
(108,3,'Ejecuta 7 curls con rango completo.'),
(108,4,'Realiza los 21 movimientos de forma consecutiva sin descanso.'),

(109,1,'Coloca la barra recta en la polea baja.'),
(109,2,'Sujeta la barra con agarre supinado y da un paso atrás.'),
(109,3,'Flexiona los codos manteniéndolos junto al torso.'),
(109,4,'Contrae el bíceps arriba.'),
(109,5,'Desciende con control.'),

(110,1,'Ajusta un banco inclinado 30-45° y túmbate boca abajo.'),
(110,2,'Sujeta la barra Z o mancuernas con brazos colgando.'),
(110,3,'Flexiona los codos manteniendo los brazos perpendiculares al suelo.'),
(110,4,'Contrae el bíceps arriba y desciende con control.'),

(111,1,'Coloca la cuerda en la polea baja.'),
(111,2,'Sujeta ambos extremos con agarre neutro.'),
(111,3,'Flexiona los codos rotando las muñecas a supinación.'),
(111,4,'Contrae el bíceps arriba.'),
(111,5,'Desciende con control.'),

(112,1,'Sujeta mancuernas con agarre supinado.'),
(112,2,'Flexiona los codos como en un curl estándar.'),
(112,3,'En la cima, rota las palmas hacia abajo (pronación).'),
(112,4,'Baja las mancuernas manteniendo la pronación.'),
(112,5,'Rota nuevamente a supinación al llegar abajo.'),

(113,1,'Pisa la banda con ambos pies al ancho de caderas.'),
(113,2,'Sujeta los extremos con agarre supinado.'),
(113,3,'Flexiona los codos venciendo la resistencia de la banda.'),
(113,4,'Contrae el bíceps arriba y desciende con control.'),

(114,1,'Sujeta la barra con agarre pronado al ancho de los hombros.'),
(114,2,'Mantén los codos pegados al torso.'),
(114,3,'Flexiona los codos elevando la barra.'),
(114,4,'Desciende con control.'),

(115,1,'Coloca el agarre en D en la polea baja.'),
(115,2,'Sujeta con la mano en supinación.'),
(115,3,'Flexiona el codo elevando el agarre hacia el hombro.'),
(115,4,'Baja con control y repite antes de cambiar de brazo.'),

(116,1,'Configura la polea alta con una barra recta o V.'),
(116,2,'Sujeta la barra con agarre pronado y codos pegados al torso.'),
(116,3,'Extiende los codos empujando la barra hacia los muslos.'),
(116,4,'Contrae el tríceps al final.'),
(116,5,'Regresa a la posición inicial con control.'),

(117,1,'Coloca la cuerda en la polea alta.'),
(117,2,'Sujeta ambos extremos con agarre neutro y codos pegados al torso.'),
(117,3,'Extiende los codos separando las manos al final del recorrido.'),
(117,4,'Contrae el tríceps abajo.'),
(117,5,'Regresa con control.'),

(118,1,'Túmbate en un banco plano con la barra Z sujeta con agarre pronado.'),
(118,2,'Extiende los brazos con codos ligeramente inclinados hacia la cabeza.'),
(118,3,'Flexiona los codos bajando la barra hacia la frente o por detrás de la cabeza.'),
(118,4,'Extiende los codos volviendo a la posición inicial.'),

(119,1,'Túmbate en un banco plano con mancuernas y brazos extendidos.'),
(119,2,'Flexiona los codos bajando las mancuernas hacia los lados de la cabeza.'),
(119,3,'Extiende los codos regresando a la posición inicial.'),
(119,4,'Mantén los codos fijos en posición durante todo el recorrido.'),

(120,1,'Siéntate o párate sujetando una mancuerna con ambas manos por encima de la cabeza.'),
(120,2,'Mantén los codos hacia el frente y pegados a la cabeza.'),
(120,3,'Flexiona los codos bajando la mancuerna detrás de la cabeza.'),
(120,4,'Extiende los codos regresando a la posición inicial.'),

(121,1,'Coloca la cuerda en la polea baja y da la espalda a la polea.'),
(121,2,'Sujeta la cuerda con las manos por encima de la cabeza.'),
(121,3,'Extiende los codos empujando la cuerda hacia arriba.'),
(121,4,'Regresa con control flexionando los codos.'),

(122,1,'Apoya una rodilla y una mano en un banco.'),
(122,2,'Sujeta una mancuerna con el brazo libre y flexiona el codo a 90°.'),
(122,3,'Mantén el codo pegado al torso y extiéndelo hacia atrás.'),
(122,4,'Contrae el tríceps al final.'),
(122,5,'Regresa a la posición inicial con control.'),

(123,1,'Apoya las palmas en el borde de un banco con dedos hacia adelante.'),
(123,2,'Extiende las piernas al frente con talones apoyados.'),
(123,3,'Flexiona los codos descendiendo hasta que los brazos formen 90°.'),
(123,4,'Empuja con los tríceps para volver a la posición inicial.'),

(124,1,'Configura la polea alta con un agarre en D.'),
(124,2,'Sujeta el agarre con una mano en pronación.'),
(124,3,'Extiende el codo empujando el agarre hacia el muslo.'),
(124,4,'Regresa con control y completa las repeticiones antes de cambiar.'),

(125,1,'Siéntate en la máquina de press horizontal con agarres estrechos.'),
(125,2,'Ajusta el asiento para que los agarres queden a la altura del pecho.'),
(125,3,'Empuja los agarres extendiendo los codos.'),
(125,4,'Regresa a la posición inicial con control.'),

(126,1,'Túmbate en banco con la barra sujeta con agarre estrecho.'),
(126,2,'Baja la barra hacia el cuello permitiendo que los codos se flexionen hacia atrás.'),
(126,3,'Detén la barra a media altura sobre el cuello.'),
(126,4,'Empuja explosivamente hasta la extensión de codos.'),

(127,1,'Siéntate con antebrazos apoyados en los muslos y palmas hacia arriba.'),
(127,2,'Deja que las mancuernas rueden hasta las yemas de los dedos.'),
(127,3,'Cierra los dedos y flexiona las muñecas para elevar las mancuernas.'),
(127,4,'Desciende con control.'),

(128,1,'Siéntate con antebrazos apoyados en los muslos y palmas hacia abajo.'),
(128,2,'Extiende las muñecas elevando las mancuernas.'),
(128,3,'Contrae al final del recorrido.'),
(128,4,'Desciende con control.'),

(129,1,'Sujeta la rueda de antebrazo con ambas manos frente a ti.'),
(129,2,'Extiende los brazos al frente a la altura del hombro.'),
(129,3,'Enrolla la cuerda alternando las muñecas hasta elevar el peso.'),
(129,4,'Desenrolla lentamente controlando la bajada.'),

(130,1,'Coloca una mancuerna o kettlebell al lado del cuerpo.'),
(130,2,'Flexiona cadera y rodillas para tomar la carga.'),
(130,3,'Levántate con la carga a un costado y el otro brazo libre.'),
(130,4,'Camina la distancia programada manteniendo el torso vertical y sin inclinarte.'),
(130,5,'Deposita la carga con seguridad y cambia de lado.'),

(131,1,'Coloca la barra en el pliegue de los codos con las manos entrelazadas.'),
(131,2,'Adopta postura erguida con torso alto y core presurizado.'),
(131,3,'Camina la distancia programada con pasos cortos.'),
(131,4,'Deposita la carga con control.'),

(132,1,'Levanta la carga por encima de la cabeza con brazo bloqueado.'),
(132,2,'Mantén el hombro empaquetado y la cabeza en posición neutra.'),
(132,3,'Camina la distancia programada manteniendo el brazo estable.'),
(132,4,'Deposita la carga con seguridad al terminar.'),

(133,1,'Sujeta la barra con agarre pronado al ancho de los hombros.'),
(133,2,'Cuelga con brazos completamente extendidos y hombros relajados.'),
(133,3,'Mantén la posición durante el tiempo objetivo respirando controladamente.'),
(133,4,'Desciende con seguridad al finalizar.'),

(134,1,'Sujeta la barra con agarre pronado.'),
(134,2,'Deprime activamente las escápulas alejándolas de las orejas.'),
(134,3,'Mantén los brazos extendidos pero con el hombro empaquetado.'),
(134,4,'Sostén la posición durante el tiempo objetivo.'),

(135,1,'Coloca dos discos con las caras lisas hacia fuera.'),
(135,2,'Presiona los discos entre sí con dedos y pulgar.'),
(135,3,'Levanta los discos manteniendo la presión.'),
(135,4,'Sostén durante el tiempo o distancia programada.'),

(136,1,'Colócate dentro de la trap bar y toma las asas.'),
(136,2,'Extiende cadera y rodillas para levantarla.'),
(136,3,'Eleva los hombros contrayendo el trapecio.'),
(136,4,'Desciende con control.'),

(137,1,'Configura la polea baja con un agarre en D.'),
(137,2,'Párate lateral a la polea con el brazo activo cruzado por delante del cuerpo.'),
(137,3,'Eleva el brazo lateralmente hasta la altura del hombro.'),
(137,4,'Desciende con control y repite antes de cambiar de lado.'),

(138,1,'Pisa la banda con un pie o ancla en un punto bajo.'),
(138,2,'Sujeta los extremos con ambas manos a los lados.'),
(138,3,'Eleva los brazos lateralmente contra la resistencia.'),
(138,4,'Desciende con control.'),

(139,1,'Adopta posición de plancha alta y desplaza los pies hacia las manos.'),
(139,2,'Eleva la cadera y forma una V invertida con el cuerpo.'),
(139,3,'Flexiona los codos bajando la cabeza hacia el suelo.'),
(139,4,'Empuja hasta la extensión completa de brazos.'),

(140,1,'Colócate en vertical invertido contra una pared.'),
(140,2,'Coloca las manos al ancho de los hombros.'),
(140,3,'Flexiona los codos descendiendo hasta que la cabeza toque el suelo o una almohadilla.'),
(140,4,'Empuja hasta la extensión completa manteniendo la línea vertical.'),

(141,1,'Colócate en vertical invertido contra la pared.'),
(141,2,'Flexiona rodillas y codos simultáneamente para descender.'),
(141,3,'Cuando la cabeza toque, extiende cadera y empuja con brazos explosivamente.'),
(141,4,'Bloquea codos arriba y repite.'),

(142,1,'Colócate cerca de una pared apoyando las manos en el suelo.'),
(142,2,'Impulsa las piernas hacia arriba llegando a la vertical.'),
(142,3,'Sostén la posición con hombros empaquetados y cuerpo alineado.'),
(142,4,'Baja de forma controlada al finalizar el tiempo.'),

(143,1,'Colócate en plancha alta con los pies contra la pared.'),
(143,2,'Camina las manos hacia la pared mientras subes los pies caminando por ella.'),
(143,3,'Llega hasta que el pecho quede cerca de la pared en vertical invertido.'),
(143,4,'Camina de vuelta a la posición inicial.'),

(144,1,'Sostén una mancuerna en cada mano a la altura de los hombros.'),
(144,2,'Adopta postura erguida con core presurizado.'),
(144,3,'Empuja las mancuernas overhead extendiendo los codos.'),
(144,4,'Baja las mancuernas con control a la altura de los hombros.'),

(145,1,'Siéntate en banco con respaldo y sujeta mancuernas a la altura de los hombros.'),
(145,2,'Presuriza el core y estabiliza la espalda contra el respaldo.'),
(145,3,'Empuja las mancuernas overhead hasta la extensión.'),
(145,4,'Baja con control.'),

(146,1,'Ancla la barra en el landmine y sujeta el extremo libre con una mano a la altura del hombro.'),
(146,2,'Adopta postura estable con el pie contralateral ligeramente adelantado.'),
(146,3,'Empuja la barra en diagonal hacia arriba y adelante extendiendo el codo.'),
(146,4,'Baja con control y completa las repeticiones antes de cambiar.'),

(147,1,'Siéntate en el suelo con las piernas extendidas al frente.'),
(147,2,'Coloca la barra en rack frontal sobre los deltoides.'),
(147,3,'Presuriza el core y mantén la espalda erguida.'),
(147,4,'Empuja la barra overhead hasta la extensión.'),
(147,5,'Baja con control al rack frontal.'),

(148,1,'Coloca la barra sobre las clavículas con agarre pronado.'),
(148,2,'Empuja la barra sobre la cabeza y bájala detrás del cuello con recorrido parcial.'),
(148,3,'Empuja la barra nuevamente arriba y bájala al frente.'),
(148,4,'Alterna delante y detrás durante toda la serie.'),

(149,1,'Coloca la barra sobre los trapecios como en la sentadilla trasera.'),
(149,2,'Adopta postura erguida y presuriza el core.'),
(149,3,'Empuja la barra overhead extendiendo los codos.'),
(149,4,'Baja la barra con control detrás del cuello a la posición inicial.'),

(150,1,'Sujeta mancuernas con agarre pronado frente a los muslos.'),
(150,2,'Realiza un remo alto elevando los codos hasta la altura de los hombros.'),
(150,3,'Rota externamente los hombros hasta que las mancuernas queden a la altura de la cabeza.'),
(150,4,'Empuja las mancuernas overhead extendiendo los codos.'),
(150,5,'Invierte la secuencia para regresar a la posición inicial.');


-- ---------- ejercicio_errores ----------
INSERT INTO ejercicio_errores (ejercicio_id, orden, titulo, descripcion) VALUES
(101,1,'Impulso de cadera','Balancear la cadera para elevar la barra.'),
(101,2,'Codos adelantados','Adelantar los codos convirtiéndolo en un press.'),
(102,1,'Rotación temprana','Rotar la palma antes de iniciar la flexión.'),
(102,2,'Codos abiertos','Abrir codos alejándolos del torso.'),
(103,1,'Impulso de cadera','Compensar con oscilación del torso.'),
(103,2,'Rango parcial','No extender los codos al final.'),
