-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(151,1,'Siéntate en la máquina con la espalda apoyada y el rodillo sobre los empeines.'),
(151,2,'Ajusta el respaldo para que las rodillas queden alineadas con el eje de la máquina.'),
(151,3,'Extiende las rodillas elevando el rodillo.'),
(151,4,'Contrae el cuádriceps arriba durante un segundo.'),
(151,5,'Desciende con control.'),
(152,1,'Túmbate boca abajo en la máquina con el rodillo apoyado sobre los talones.'),
(152,2,'Sujeta las asas y presuriza el core.'),
(152,3,'Flexiona las rodillas llevando los talones hacia los glúteos.'),
(152,4,'Contrae los isquiotibiales arriba y desciende con control.'),
(153,1,'Siéntate en la máquina con las piernas extendidas y el rodillo sobre los talones.'),
(153,2,'Ajusta el respaldo para que las rodillas queden alineadas.'),
(153,3,'Flexiona las rodillas llevando los talones hacia el asiento.'),
(153,4,'Regresa a la posición inicial con control.'),
(154,1,'Ajusta la tobillera y sitúate frente a la máquina.'),
(154,2,'Flexiona la rodilla elevando el talón hacia el glúteo.'),
(154,3,'Contrae el isquiotibial y desciende con control.'),
(154,4,'Completa las repeticiones y cambia de pierna.'),
(155,1,'Arrodíllate con las tibias fijas por un compañero o rodillera.'),
(155,2,'Presuriza el core y mantén el cuerpo alineado.'),
(155,3,'Baja el torso hacia adelante controlando con los isquios.'),
(155,4,'Al perder el control, apoya las manos y empuja para volver.'),
(156,1,'Apoya la espalda alta en un banco.'),
(156,2,'Coloca un pie firme y eleva la otra pierna.'),
(156,3,'Empuja las caderas hacia arriba con la pierna de apoyo.'),
(156,4,'Alcanza la extensión completa y desciende con control.'),
(157,1,'Ajusta la máquina con la almohadilla sobre la cadera.'),
(157,2,'Coloca los pies firmes al ancho de hombros.'),
(157,3,'Extiende la cadera empujando la almohadilla hacia arriba.'),
(157,4,'Desciende con control.'),
(158,1,'Ajusta la tobillera en la polea baja.'),
(158,2,'Sujétate de la máquina y adopta postura ligeramente inclinada.'),
(158,3,'Extiende la cadera llevando la pierna hacia atrás.'),
(158,4,'Contrae el glúteo arriba y regresa con control.'),
(159,1,'Coloca una cuerda en la polea baja y colócate de espaldas a la polea.'),
(159,2,'Adopta stance amplio con la cuerda entre las piernas.'),
(159,3,'Empuja las caderas hacia atrás flexionando ligeramente rodillas.'),
(159,4,'Extiende la cadera empujando la cuerda hacia adelante y contrayendo glúteo.'),
(160,1,'Siéntate en la máquina con las piernas separadas contra los rodillos externos.'),
(160,2,'Presiona hacia fuera contra la resistencia.'),
(160,3,'Contrae el glúteo medio al final del recorrido.'),
(160,4,'Regresa con control.'),
(161,1,'Siéntate en la máquina con las piernas separadas contra los rodillos internos.'),
(161,2,'Presiona hacia dentro contrayendo aductores.'),
(161,3,'Regresa con control sin dejar caer la carga.'),
(161,4,'Mantén tensión constante durante toda la serie.'),
(162,1,'Adopta stance amplio con puntas rotadas hacia fuera.'),
(162,2,'Sujeta una mancuerna con ambas manos entre las piernas.'),
(162,3,'Desciende manteniendo torso vertical.'),
(162,4,'Empuja el suelo para volver a la posición inicial.'),
(163,1,'Colócate arrodillado con los pies fijos bajo un soporte.'),
(163,2,'Sujeta una carga en el pecho para mayor dificultad.'),
(163,3,'Inclina el torso hacia atrás manteniendo cadera extendida.'),
(163,4,'Contrae los cuádriceps para volver a la posición inicial.'),
(164,1,'Coloca la almohadilla sobre los hombros y las puntas de los pies en la plataforma.'),
(164,2,'Deja caer los talones para estirar los gemelos.'),
(164,3,'Eleva los talones contrayendo los gemelos al máximo.'),
(164,4,'Desciende con control.'),
(165,1,'Siéntate con las almohadillas sobre las rodillas y puntas en la plataforma.'),
(165,2,'Deja caer los talones estirando el sóleo.'),
(165,3,'Eleva los talones contrayendo el sóleo.'),
(165,4,'Desciende con control.'),
(166,1,'Ajusta la prensa y coloca las puntas de los pies en el borde de la plataforma.'),
(166,2,'Extiende las rodillas parcialmente y desbloquea la máquina.'),
(166,3,'Empuja con las puntas extendiendo el tobillo.'),
(166,4,'Regresa con control hasta estirar los gemelos.'),
(167,1,'Colócate sobre un escalón con la punta de un pie apoyada.'),
(167,2,'Deja caer el talón para estirar el gemelo.'),
(167,3,'Eleva el talón contrayendo el gemelo.'),
(167,4,'Desciende con control y cambia de pierna.'),
(168,1,'Inclínate hacia adelante apoyando el torso sobre un banco.'),
(168,2,'Coloca las puntas de los pies en una plataforma y carga sobre la cadera.'),
(168,3,'Eleva los talones contrayendo los gemelos.'),
(168,4,'Desciende con control.'),
(169,1,'Apoya la espalda en una pared con los talones a unos 30 cm de ella.'),
(169,2,'Levanta las puntas de los pies dorsiflexionando los tobillos.'),
(169,3,'Contrae el tibial anterior arriba.'),
(169,4,'Baja las puntas con control.'),
(170,1,'Túmbate boca abajo en el reverse hyper con las piernas colgando.'),
(170,2,'Sujeta las asas laterales.'),
(170,3,'Eleva las piernas contrayendo glúteos e isquiotibiales.'),
(170,4,'Desciende con control hasta la vertical.'),
(171,1,'Ajusta el banco romano con las almohadillas debajo de la cadera y talones anclados.'),
(171,2,'Cruza los brazos sobre el pecho o sujeta un disco.'),
(171,3,'Flexiona la cadera bajando el torso.'),
(171,4,'Extiende la cadera regresando a la línea neutra sin hiperextender.'),
(172,1,'Ajusta el GHD con las rodillas por delante de las almohadillas.'),
(172,2,'Túmbate hacia atrás con brazos cruzados o extendidos.'),
(172,3,'Flexiona la cadera y torso simultáneamente incorporándote.'),
(172,4,'Toca las puntas de los pies y regresa con control.'),
(173,1,'Ajusta el GHD con la cadera sobre las almohadillas y talones anclados.'),
(173,2,'Deja caer el torso hacia adelante con la espalda neutra.'),
(173,3,'Extiende la cadera contrayendo glúteos e isquios.'),
(173,4,'Regresa a la posición horizontal sin hiperextender.'),
(174,1,'Apoya la pierna superior sobre un banco a la altura de la rodilla.'),
(174,2,'Coloca el antebrazo inferior apoyado en el suelo.'),
(174,3,'Levanta la cadera formando línea recta y aductor contra el banco.'),
(174,4,'Sostén la posición durante el tiempo objetivo.'),
(175,1,'Adopta stance muy amplio con puntas ligeramente hacia fuera.'),
(175,2,'Desciende hacia un lado flexionando esa rodilla.'),
(175,3,'La otra pierna queda extendida con la punta hacia arriba.'),
(175,4,'Regresa al centro y desciende hacia el otro lado.'),
(176,1,'Sujeta una mancuerna ligera con ambas manos.'),
(176,2,'Colócate sobre una superficie elevada con piernas casi extendidas.'),
(176,3,'Flexiona la columna articulando vértebra por vértebra hacia abajo.'),
(176,4,'Rueda hacia arriba articulando vértebra por vértebra.'),
(177,1,'Colócate arrodillado con las tibias fijas.'),
(177,2,'Extiende la cadera y bloquea glúteos.'),
(177,3,'Inclina el torso hacia atrás con el cuerpo recto controlando con cuádriceps.'),
(177,4,'Regresa a la posición inicial contrayendo cuádriceps.'),
(178,1,'Apoya la espalda en una pared.'),
(178,2,'Desciende hasta que las rodillas queden a 90°.'),
(178,3,'Mantén la posición durante el tiempo objetivo.'),
(178,4,'Presuriza el core y respira controladamente.'),
(179,1,'Sujeta las asas del sled con el sled a tu espalda.'),
(179,2,'Camina hacia atrás con pasos cortos.'),
(179,3,'Extiende activamente las rodillas en cada paso.'),
(179,4,'Mantén el torso ligeramente inclinado hacia adelante.'),
