-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(201,1,'Desde de pie, agáchate y coloca las manos en el suelo.'),
(201,2,'Salta o desplaza los pies hacia atrás llegando a plancha.'),
(201,3,'Baja el pecho al suelo (contacto pleno).'),
(201,4,'Empuja y salta o desplaza los pies hacia las manos.'),
(201,5,'Termina con un salto vertical y palmada por encima de la cabeza.'),
(202,1,'Colócate junto a una barra en el suelo.'),
(202,2,'Ejecuta un burpee con caída al suelo.'),
(202,3,'Levántate y salta lateralmente por encima de la barra con dos pies.'),
(202,4,'Ejecuta el siguiente burpee al otro lado y repite.'),
(203,1,'Colócate junto a un cajón.'),
(203,2,'Ejecuta un burpee con contacto pleno del pecho.'),
(203,3,'Levántate y salta lateralmente sobre el cajón atravesándolo.'),
(203,4,'Aterriza al otro lado y ejecuta el siguiente burpee.'),
(204,1,'Colócate frente al cajón con los pies al ancho de caderas.'),
(204,2,'Flexiona cadera y rodillas y balancea los brazos hacia atrás.'),
(204,3,'Salta explosivamente extendiendo cadera y rodillas.'),
(204,4,'Aterriza con dos pies en el cajón absorbiendo con rodillas semiflexionadas.'),
(204,5,'Extiende la cadera arriba y baja controladamente.'),
(205,1,'Colócate lateral al cajón.'),
(205,2,'Salta al cajón o directamente sobre él.'),
(205,3,'Al aterrizar, baja al otro lado.'),
(205,4,'Ejecuta la siguiente repetición desde el nuevo lado.'),
(206,1,'Sujeta el balón medicinal frente al pecho.'),
(206,2,'Adopta stance de sentadilla y desciende a profundidad completa.'),
(206,3,'Empuja el suelo explosivamente y lanza el balón al objetivo en la pared.'),
(206,4,'Recíbelo con brazos suaves y encadena la siguiente sentadilla.'),
(207,1,'Coloca la barra en rack frontal sobre los deltoides.'),
(207,2,'Ejecuta una sentadilla frontal a profundidad completa.'),
(207,3,'Al subir, transfiere la potencia de las piernas hacia un push press.'),
(207,4,'Bloquea la barra overhead y baja al rack frontal.'),
(208,1,'Sujeta mancuernas en rack frontal apoyadas en los deltoides.'),
(208,2,'Ejecuta una sentadilla frontal a profundidad completa.'),
(208,3,'Al subir, empuja las mancuernas overhead extendiendo los codos.'),
(208,4,'Baja al rack frontal y repite.'),
(209,1,'Coloca la kettlebell entre las piernas con stance al ancho de caderas.'),
(209,2,'Ejecuta bisagra de cadera balanceando la kettlebell hacia atrás entre las piernas.'),
(209,3,'Extiende la cadera explosivamente proyectando la kettlebell al frente.'),
(209,4,'Detén el swing a la altura del pecho y controla el descenso.'),
(210,1,'Ejecuta un swing ruso hasta la altura del pecho.'),
(210,2,'Continúa el impulso llevando la kettlebell overhead.'),
(210,3,'Bloquea los codos con la kettlebell alineada sobre la cabeza.'),
(210,4,'Deja caer la kettlebell y encadena la siguiente repetición.'),
(211,1,'Coloca la kettlebell entre las piernas y toma el asa con una mano.'),
(211,2,'Ejecuta un swing corto extendiendo la cadera.'),
(211,3,'A la altura del abdomen, "envuelve" la kettlebell rotando la muñeca hasta el rack frontal.'),
(211,4,'Deja caer la kettlebell con control regresando entre las piernas.'),
