-- ---------- ejercicio_instrucciones ----------
INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, instruccion) VALUES
(251,1,'Colócate en cuadrupedia con manos bajo hombros y rodillas bajo caderas.'),
(251,2,'Inhala y arquea la espalda hacia abajo llevando la mirada al techo (vaca).'),
(251,3,'Exhala redondeando la espalda hacia arriba (gato).'),
(251,4,'Alterna suavemente entre ambas posiciones.'),
(252,1,'Colócate en cuadrupedia con espalda neutra.'),
(252,2,'Extiende un brazo al frente y la pierna contraria hacia atrás.'),
(252,3,'Mantén la posición 1-2 segundos activando el core.'),
(252,4,'Alterna con el brazo y pierna opuestos.'),
(253,1,'Da un paso amplio hacia adelante en zancada profunda.'),
(253,2,'Apoya la mano contraria al pie adelantado junto al pie.'),
(253,3,'Rota el torso llevando el brazo del mismo lado hacia el techo.'),
(253,4,'Regresa y estira la pierna adelantada extendiendo la rodilla.'),
(253,5,'Vuelve a la posición inicial y cambia de pierna.'),
(254,1,'Desde plancha alta, eleva la cadera hacia arriba y atrás.'),
(254,2,'Extiende brazos y piernas formando una V invertida.'),
(254,3,'Empuja los talones hacia el suelo estirando la cadena posterior.'),
(254,4,'Mantén la posición respirando profundamente.'),
(255,1,'Túmbate boca abajo con las palmas apoyadas junto al pecho.'),
(255,2,'Extiende los codos elevando el pecho del suelo.'),
(255,3,'Mantén la cadera y las piernas relajadas contra el suelo.'),
(255,4,'Sostén la posición respirando profundamente.'),
(256,1,'Arrodíllate con los dedos gordos juntos y rodillas separadas.'),
(256,2,'Siéntate sobre los talones y extiende los brazos al frente.'),
(256,3,'Apoya la frente en el suelo relajando la columna.'),
(256,4,'Mantén la posición respirando profundamente.'),
(257,1,'Desde cuadrupedia, adelanta una pierna cruzándola bajo el torso.'),
(257,2,'Extiende la pierna contraria hacia atrás.'),
(257,3,'Descansa la cadera sobre el suelo o bloque.'),
(257,4,'Inclina el torso hacia adelante para mayor estiramiento.'),
(257,5,'Sostén y cambia de pierna.'),
(258,1,'Colócate en cuadrupedia y separa las rodillas al máximo.'),
(258,2,'Coloca los tobillos en línea con las rodillas.'),
(258,3,'Empuja las caderas hacia atrás manteniendo espalda neutra.'),
(258,4,'Mantén la posición respirando profundamente.'),
(259,1,'Siéntate con las plantas de los pies juntas y rodillas hacia fuera.'),
(259,2,'Sujeta los pies con las manos.'),
(259,3,'Empuja suavemente las rodillas hacia el suelo.'),
(259,4,'Inclina el torso hacia adelante para mayor estiramiento.'),
(260,1,'Siéntate con las piernas extendidas al frente.'),
(260,2,'Inclina el torso hacia adelante alcanzando los pies.'),
(260,3,'Mantén la espalda lo más recta posible.'),
(260,4,'Sostén respirando profundamente.'),
(261,1,'Párate con los pies al ancho de caderas.'),
(261,2,'Flexiona la cadera bajando el torso.'),
(261,3,'Deja caer los brazos hacia el suelo con rodillas ligeramente flexionadas.'),
(261,4,'Sostén la posición respirando profundamente.'),
(262,1,'Siéntate con una pierna adelante flexionada a 90° y la otra a 90° al lado.'),
(262,2,'Mantén ambas rodillas apoyadas en el suelo si es posible.'),
(262,3,'Inclina el torso sobre la pierna adelantada para estirar el glúteo.'),
(262,4,'Alterna cambiando la posición de las piernas.'),
(263,1,'Coloca una rodilla contra la pared con la tibia vertical apoyada.'),
(263,2,'Adelanta la otra pierna en zancada apoyando el pie firmemente.'),
(263,3,'Empuja la cadera hacia adelante estirando cuádriceps y flexor de cadera.'),
(263,4,'Sostén y cambia de pierna.'),
(264,1,'Adopta una zancada profunda con la rodilla trasera apoyada.'),
(264,2,'Coloca la mano contraria al pie delantero en el suelo junto al pie.'),
(264,3,'Rota el torso llevando el brazo homolateral al techo.'),
(264,4,'Regresa y alterna repeticiones antes de cambiar de pierna.'),
(265,1,'Desde cuadrupedia, apoya el peso en una mano y la rodilla contraria.'),
(265,2,'Eleva la cadera y rota el torso llevando el brazo libre al techo.'),
(265,3,'Regresa con control y alterna al otro lado.'),
(265,4,'Mantén flujo controlado entre ambos lados.'),
(266,1,'Apoya la espalda, glúteos y cabeza contra la pared.'),
(266,2,'Coloca los brazos en forma de "W" contra la pared.'),
(266,3,'Desliza los brazos hacia arriba manteniendo contacto con la pared.'),
(266,4,'Regresa a la "W" con control.'),
(267,1,'Colócate en un marco de puerta y apoya el antebrazo con el codo a 90°.'),
(267,2,'Da un paso hacia adelante estirando el pectoral.'),
(267,3,'Mantén el hombro deprimido durante el estiramiento.'),
(267,4,'Sostén y cambia de lado.'),
(268,1,'Túmbate boca abajo con el foam roller bajo un muslo.'),
(268,2,'Desplázate lentamente rodando por todo el cuádriceps.'),
(268,3,'Detente en puntos tensos y respira profundamente.'),
(268,4,'Cambia de pierna y repite.'),
(269,1,'Túmbate de lado con el foam roller bajo el dorsal.'),
(269,2,'Extiende el brazo del mismo lado por encima de la cabeza.'),
(269,3,'Rueda desde la axila hasta la parte baja del dorsal.'),
(269,4,'Detén en puntos tensos y cambia de lado.'),
(270,1,'Túmbate de lado con el foam roller bajo la banda iliotibial.'),
(270,2,'Rueda desde la cadera hasta encima de la rodilla.'),
(270,3,'Regula presión con la otra pierna apoyada.'),
(270,4,'Detente en puntos tensos y respira.'),
(271,1,'Siéntate con el foam roller bajo un gemelo y la otra pierna apoyada encima.'),
(271,2,'Levanta la cadera del suelo y rueda por todo el gemelo.'),
(271,3,'Rueda desde la parte alta hasta el tobillo.'),
(271,4,'Cambia de pierna.'),
(272,1,'Túmbate boca arriba con el foam roller bajo la parte alta de la espalda.'),
(272,2,'Coloca las manos detrás de la cabeza.'),
(272,3,'Rueda de arriba a abajo por los erectores.'),
(272,4,'Evita rodar sobre la zona lumbar directamente.'),
(273,1,'Túmbate boca abajo con una pierna flexionada al lado y el foam roller bajo el aductor.'),
(273,2,'Rueda desde la ingle hasta encima de la rodilla.'),
(273,3,'Regula presión con la otra pierna.'),
(273,4,'Cambia de lado.'),
(274,1,'Siéntate con la pelota bajo un glúteo.'),
(274,2,'Cruza la pierna del mismo lado sobre la otra.'),
(274,3,'Rueda y presiona sobre puntos tensos.'),
(274,4,'Sostén 30-60 segundos y cambia de lado.'),
(275,1,'Apoya la pelota entre el trapecio superior y una pared.'),
(275,2,'Presiona el cuerpo contra la pelota buscando puntos tensos.'),
(275,3,'Rueda suavemente por el trapecio.'),
(275,4,'Cambia de lado.'),
(276,1,'Apoya la pelota entre el pectoral y una pared.'),
(276,2,'Presiona el cuerpo contra la pelota buscando puntos tensos.'),
(276,3,'Mueve el brazo del mismo lado para movilizar el pectoral.'),
(276,4,'Cambia de lado.'),
(277,1,'Colócate de pie con la pelota bajo el arco del pie.'),
(277,2,'Presiona con el peso del cuerpo.'),
(277,3,'Rueda desde el talón hasta los dedos.'),
(277,4,'Cambia de pie.'),
(278,1,'Sitúate erguido y realiza movimientos suaves de flexión y extensión de cuello.'),
(278,2,'Añade rotaciones laterales al máximo rango cómodo.'),
(278,3,'Combina con inclinaciones laterales.'),
(278,4,'Realiza rotaciones lentas de 360° si el rango lo permite.'),
(279,1,'De pie con brazos extendidos a los lados.'),
(279,2,'Rota lentamente un brazo describiendo un círculo grande hacia atrás.'),
(279,3,'Alcanza el máximo rango posible manteniendo el hombro empaquetado.'),
(279,4,'Cambia de brazo y repite.'),
(280,1,'De pie sujetado a un soporte.'),
(280,2,'Eleva una rodilla y rota la cadera describiendo un círculo grande.'),
(280,3,'Alcanza el máximo rango posible manteniendo el core activo.'),
(280,4,'Alterna direcciones y cambia de pierna.'),
(281,1,'Extiende un brazo al frente con la muñeca relajada.'),
(281,2,'Rota la muñeca describiendo círculos completos.'),
(281,3,'Alterna direcciones.'),
(281,4,'Cambia de brazo.'),
(282,1,'Sentado o de pie con una pierna elevada.'),
(282,2,'Rota el tobillo describiendo círculos completos.'),
(282,3,'Alterna direcciones.'),
(282,4,'Cambia de pierna.'),
(283,1,'Ancla una banda a la altura del codo.'),
(283,2,'Sujeta la banda con el brazo del lado contrario al anclaje, codo a 90°.'),
(283,3,'Rota externamente el hombro alejando la mano del cuerpo.'),
(283,4,'Regresa con control y completa antes de cambiar de brazo.'),
(284,1,'Ancla una banda a la altura del codo.'),
(284,2,'Sujeta la banda con el brazo del mismo lado del anclaje, codo a 90°.'),
(284,3,'Rota internamente llevando la mano hacia el abdomen.'),
(284,4,'Regresa con control.'),
(285,1,'Túmbate boca abajo en un banco inclinado con mancuernas ligeras.'),
(285,2,'Eleva los brazos al frente formando una Y con los pulgares hacia arriba.'),
(285,3,'Sostén brevemente arriba.'),
(285,4,'Desciende con control.'),
(286,1,'Túmbate boca abajo en un banco inclinado con mancuernas.'),
(286,2,'Eleva los brazos a los lados formando una T.'),
(286,3,'Sostén brevemente contrayendo escápulas.'),
(286,4,'Desciende con control.'),
(287,1,'Túmbate boca abajo en banco inclinado con mancuernas.'),
(287,2,'Flexiona los codos a 90° y retrae escápulas formando una W.'),
(287,3,'Sostén brevemente.'),
(287,4,'Desciende con control.'),
(288,1,'Cuelga de la barra con brazos extendidos.'),
(288,2,'Sin flexionar los codos, deprime las escápulas hacia abajo.'),
(288,3,'Eleva el cuerpo unos centímetros por depresión escapular.'),
(288,4,'Desciende con control.'),
(289,1,'Adopta posición de plancha alta con brazos rectos.'),
(289,2,'Sin flexionar codos, protruye las escápulas alejándolas de la columna.'),
(289,3,'Retrae las escápulas juntándolas.'),
(289,4,'Alterna con control.'),
(290,1,'Túmbate boca arriba con caderas y rodillas flexionadas a 90°.'),
(290,2,'Extiende los brazos hacia el techo.'),
(290,3,'Extiende un brazo por encima de la cabeza y la pierna contraria hasta casi tocar el suelo.'),
(290,4,'Regresa a la posición inicial y alterna.'),
(291,1,'Adopta plancha alta sujetando dos mancuernas.'),
(291,2,'Presuriza el core y estabiliza la cadera.'),
(291,3,'Ejecuta un remo con una mancuerna llevándola a la cadera.'),
(291,4,'Baja con control y alterna brazos.'),
(292,1,'Adopta cuadrupedia y eleva las rodillas del suelo unos centímetros.'),
(292,2,'Alinea espalda, cabeza y rodillas.'),
(292,3,'Mantén el core activo y las escápulas empaquetadas.'),
(292,4,'Sostén durante el tiempo objetivo.'),
(293,1,'Adopta stance de sentadilla.'),
(293,2,'Desciende hasta la profundidad completa.'),
(293,3,'Mantén torso vertical, talones en el suelo y core activo.'),
(293,4,'Sostén durante el tiempo objetivo respirando.'),
(294,1,'Apoya la espalda contra una pared con los pies ligeramente separados.'),
(294,2,'Coloca los brazos en "W" contra la pared.'),
(294,3,'Desliza los brazos hacia arriba manteniendo codos y muñecas en contacto.'),
(294,4,'Regresa con control.'),
(295,1,'Túmbate boca arriba sosteniendo una mancuerna con el brazo extendido hacia el techo.'),
(295,2,'Empuja la mancuerna hacia el techo alejando el omóplato de la columna.'),
(295,3,'Regresa retrayendo el omóplato.'),
(295,4,'Repite manteniendo el codo extendido.'),
(296,1,'Sujeta una banda con ambas manos al ancho de los hombros frente al pecho.'),
(296,2,'Separa las manos abriendo la banda hasta que roce el pecho.'),
(296,3,'Aprieta las escápulas al final.'),
(296,4,'Regresa con control.'),
(297,1,'Sujeta una banda al ancho suficiente con ambas manos frente al cuerpo.'),
(297,2,'Con brazos extendidos, pasa la banda por encima de la cabeza y hacia atrás.'),
(297,3,'Regresa al frente pasando la banda por encima nuevamente.'),
(297,4,'Aumenta gradualmente la anchura del agarre para mayor rango.'),
(298,1,'Junta las palmas de las manos frente al pecho en posición de oración.'),
(298,2,'Baja las manos hasta la altura del abdomen manteniendo las palmas juntas.'),
(298,3,'Alcanza el estiramiento cómodo de los flexores del antebrazo.'),
(298,4,'Sostén respirando profundamente.'),
(299,1,'Siéntate erguido y lleva una oreja hacia el hombro del mismo lado.'),
(299,2,'Coloca la mano del mismo lado sobre la cabeza aplicando presión suave.'),
(299,3,'Mantén el hombro contrario deprimido.'),
(299,4,'Sostén y cambia de lado.'),
(300,1,'Túmbate boca arriba con las rodillas flexionadas.'),
(300,2,'Cruza el tobillo de una pierna sobre la rodilla contraria.'),
(300,3,'Sujeta el muslo de la pierna de abajo y llévalo hacia el pecho.'),
(300,4,'Sostén y cambia de lado.');


