INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, texto) VALUES
(351,1,'Coloca la barra en el suelo con carga y sitúate con pies al ancho de caderas.'),
(351,2,'Flexiona cadera manteniendo torso paralelo al suelo y agarra la barra al ancho de hombros.'),
(351,3,'Rema explosivamente hasta el abdomen bajo con los codos pegados al torso.'),
(351,4,'Devuelve la barra al suelo en cada repetición y reinicia el movimiento.'),
(351,5,'Mantén el torso rígido y evita usar impulso de cadera.'),
(352,1,'Sujeta la barra en supinación al ancho de hombros y flexiona cadera unos 45°.'),
(352,2,'Rema hacia el ombligo bajo con codos pegados al torso.'),
(352,3,'Aprieta escápulas al final del recorrido.'),
(352,4,'Baja la carga controlada sin permitir que la espalda se redondee.'),
(353,1,'Apóyate con una mano y una rodilla en un banco firme.'),
(353,2,'Sujeta la mancuerna con el brazo libre y aprovecha algo de body English controlado.'),
(353,3,'Rema con potencia hacia la cadera hasta contracción máxima.'),
(353,4,'Baja controlado buscando estiramiento completo del dorsal.'),
(354,1,'Sujeta la barra con agarre supino estrecho y torso a 45° del suelo.'),
(354,2,'Rema con codos pegados al torso hasta el abdomen bajo.'),
(354,3,'Aprieta escápulas y contrae dorsal bajo al final.'),
(354,4,'Baja controlado sin perder la posición del torso.'),
(355,1,'Coloca la T-bar cargada bajo un banco inclinado y túmbate boca abajo.'),
(355,2,'Sujeta los agarres con las manos y comienza con brazos extendidos.'),
(355,3,'Rema tirando los codos hacia atrás y aprieta escápulas.'),
(355,4,'Baja controlado y repite.'),
(356,1,'Carga un extremo de la barra tipo landmine y agarra con una mano el otro extremo.'),
(356,2,'Coloca el pie contralateral adelantado y apoya la mano libre en el muslo.'),
(356,3,'Rema tirando el codo hacia atrás y arriba en línea con el hombro.'),
(356,4,'Baja controlado buscando estiramiento en el dorsal.'),
(357,1,'Ajusta un banco a unos 30° y túmbate boca abajo con una mancuerna en cada mano.'),
(357,2,'Comienza con los brazos colgando y omóplatos protraídos.'),
(357,3,'Rema simultáneamente hacia el costado de las costillas.'),
(357,4,'Aprieta escápulas y baja controlado.'),
(358,1,'Siéntate en la máquina con triangle bar y pies firmes en la plataforma.'),
(358,2,'Torso vertical y brazos extendidos al inicio.'),
(358,3,'Rema tirando los codos hacia atrás pegados al torso.'),
(358,4,'Aprieta escápulas y baja controlado sin dejar caer el peso.'),
(359,1,'Siéntate en la máquina con barra recta y pies firmes en la plataforma.'),
(359,2,'Torso vertical, brazos extendidos y codos altos.'),
(359,3,'Rema tirando la barra hacia el pecho bajo con codos abiertos.'),
(359,4,'Aprieta escápulas y baja controlado.'),
(360,1,'Túmbate boca abajo sobre un banco alto con la barra o mancuernas colgando.'),
(360,2,'Con brazos extendidos, rema hacia el pecho.'),
(360,3,'Aprieta escápulas y baja controlado sin balancear el torso.'),
(360,4,'Repite manteniendo pecho fijo en el banco.'),
(361,1,'Túmbate transversal en un banco solo con los omóplatos apoyados.'),
(361,2,'Sujeta una mancuerna con ambas manos sobre el pecho, codos ligeramente flexionados.'),
(361,3,'Baja la mancuerna hacia atrás describiendo un arco hasta estirar el dorsal.'),
(361,4,'Regresa contrayendo el dorsal sin extender los codos por completo.'),
(362,1,'Ajusta polea alta con barra recta o cuerda y párate a distancia.'),
(362,2,'Sujeta la barra con brazos rectos y codos ligeramente bloqueados.'),
(362,3,'Tira hacia los muslos manteniendo brazos rectos y torso fijo.'),
(362,4,'Contrae dorsal ancho y regresa controlado.'),
(363,1,'Siéntate en la máquina con muslos bajo el rodillo y agarre neutro paralelo.'),
(363,2,'Comienza con brazos extendidos y ligera extensión torácica.'),
(363,3,'Jala la barra hacia la clavícula manteniendo codos apuntando abajo.'),
(363,4,'Aprieta dorsales y regresa controlado.'),
(364,1,'Siéntate con muslos fijos bajo el rodillo y agarre supino al ancho de hombros.'),
(364,2,'Jala la barra hacia el pecho alto conduciendo con los codos.'),
(364,3,'Aprieta dorsales y bíceps al final del recorrido.'),
(364,4,'Regresa lento controlando el estiramiento.'),
