INSERT INTO ejercicio_instrucciones (ejercicio_id, orden, texto) VALUES
(401,1,'Siéntate en un banco con antebrazos apoyados sobre los muslos y mancuernas en supinación.'),
(401,2,'Deja caer las muñecas permitiendo extensión completa.'),
(401,3,'Flexiona las muñecas elevando las mancuernas.'),
(401,4,'Baja controlado.'),
(402,1,'Siéntate con antebrazos apoyados sobre los muslos y agarre pronado con barra o mancuerna.'),
(402,2,'Deja caer las muñecas permitiendo flexión completa.'),
(402,3,'Extiende las muñecas elevando el peso hacia arriba.'),
(402,4,'Baja controlado permitiendo flexión completa.'),
(403,1,'Sujeta el rodillo horizontalmente con ambas manos a la altura de los hombros.'),
(403,2,'Enrolla la cuerda subiendo el peso girando las muñecas alternadamente.'),
(403,3,'Al llegar al tope, desenrolla lentamente controlando el descenso.'),
(403,4,'Mantén los brazos extendidos al frente durante todo el ejercicio.'),
(404,1,'Sujeta la barra con agarre pronado al ancho de hombros.'),
(404,2,'Cuelga completamente con brazos extendidos y cuerpo relajado.'),
(404,3,'Mantén la posición el máximo tiempo posible.'),
(404,4,'Baja al suelo controlado.'),
(405,1,'Sujeta la barra con agarre pronado al ancho de hombros.'),
(405,2,'Cuelga con brazos extendidos.'),
(405,3,'Deprime las escápulas activamente sin flexionar los codos.'),
(405,4,'Activa el core y mantén la posición.'),
(406,1,'Sujeta la barra con agarre pronado y cuelga activo.'),
(406,2,'Eleva las piernas rectas hasta la horizontal formando una L.'),
(406,3,'Mantén la posición contrayendo el core y flexores de cadera.'),
(406,4,'Baja controlado las piernas.'),
(407,1,'Siéntate en banco con respaldo vertical y barra en el rack a la altura del pecho.'),
(407,2,'Desmonta la barra con agarre al ancho de hombros justo por fuera.'),
(407,3,'Presiona la barra verticalmente hasta bloquear los codos.'),
(407,4,'Baja controlado a la clavícula.'),
(407,5,'Mantén el core rígido durante toda la ejecución.'),
(408,1,'Siéntate en banco con respaldo vertical y mancuernas frente a los hombros en supinación.'),
(408,2,'Presiona las mancuernas hacia arriba rotando gradualmente hasta pronación.'),
(408,3,'Termina con los brazos extendidos overhead con palmas hacia adelante.'),
(408,4,'Baja controlado rotando de vuelta a supinación.'),
(409,1,'Ajusta el asiento de la máquina para que los agarres queden a la altura de los hombros.'),
(409,2,'Sujeta los agarres y presiona verticalmente extendiendo los codos.'),
(409,3,'Baja controlado sin dejar chocar los pesos abajo.'),
(410,1,'De pie con barra al frente de los hombros, agarre al ancho justo por fuera de los hombros.'),
(410,2,'Presiona la barra hasta encima de la cabeza sin bloquear codos.'),
(410,3,'Baja controlado detrás de la nuca hasta la parte alta del trapecio.'),
(410,4,'Vuelve a presionar arriba sin bloquear.'),
(410,5,'Baja al frente y repite el ciclo alternando.'),
(411,1,'Sujeta las mancuernas en el rack con codos altos frente a los hombros.'),
(411,2,'Realiza un pequeño dip flexionando ligeramente las rodillas.'),
(411,3,'Extiende explosivamente las piernas transmitiendo el impulso a las mancuernas.'),
(411,4,'Bloquea las mancuernas overhead con brazos extendidos.'),
(411,5,'Baja controlado a la posición inicial.'),
(412,1,'Sujeta las mancuernas en rack a la altura de los hombros.'),
(412,2,'Realiza un dip explosivo con las piernas.'),
(412,3,'Simultáneamente separa las piernas en split y presiona las mancuernas overhead.'),
(412,4,'Bloquea los brazos y estabiliza la posición split.'),
(412,5,'Recupera trayendo primero el pie de atrás y luego el de adelante.'),
(413,1,'Sujeta una mancuerna en rack a la altura del hombro con la otra mano en la cadera.'),
(413,2,'Realiza dip con las piernas.'),
(413,3,'Presiona la mancuerna overhead usando el impulso de piernas.'),
(413,4,'Bloquea el brazo y baja controlado al rack.'),
(414,1,'Siéntate o párate con mancuerna en el hombro con la palma hacia adentro o al frente.'),
(414,2,'Presiona la mancuerna verticalmente hasta extensión completa.'),
(414,3,'Baja controlado al hombro.'),
(415,1,'Siéntate en el suelo con las piernas extendidas y la barra en un rack a la altura del pecho.'),
(415,2,'Sujeta la barra al ancho de hombros justo por fuera.'),
(415,3,'Desmonta y presiona verticalmente hasta extensión completa.'),
(415,4,'Mantén el torso vertical y las piernas extendidas activadas.'),
(415,5,'Baja controlado a la clavícula.'),
(416,1,'Sujeta la barra en la espalda alta con agarre ancho.'),
(416,2,'Presiona la barra verticalmente hacia arriba.'),
(416,3,'Bloquea los codos overhead.'),
(416,4,'Baja controlado detrás de la nuca hasta la posición inicial.'),
(417,1,'De pie con mancuernas al frente de los muslos.'),
(417,2,'Realiza un remo alto elevando las mancuernas hasta la altura de los hombros.'),
(417,3,'Rota externamente los hombros llevando las mancuernas frente a los hombros.'),
(417,4,'Presiona verticalmente overhead extendiendo los codos.'),
(417,5,'Invierte el movimiento controlado.'),
(418,1,'Túmbate en el suelo con la barra sobre el pecho.'),
(418,2,'Sujeta la barra con agarre ligeramente más ancho que los hombros.'),
(418,3,'Presiona la barra verticalmente extendiendo los codos.'),
(418,4,'Baja hasta que los codos toquen el suelo y haz una pausa breve.'),
(418,5,'Presiona de vuelta arriba.'),
