(419,2,'Baja las mancuernas hasta que los codos toquen el suelo.'),
(419,3,'Presiona de vuelta hacia arriba.'),
(419,4,'Mantén los codos a 45° del torso.'),
(420,1,'Túmbate en banco plano con piernas sobre el banco o flotando.'),
(420,2,'Desmonta la barra con agarre estándar.'),
(420,3,'Baja controlado al pecho manteniendo escápulas retraídas.'),
(420,4,'Presiona verticalmente sin usar leg drive.'),
(421,1,'Ajusta pines en el rack a la altura deseada de trabajo.'),
(421,2,'Coloca la barra sobre los pines y túmbate bajo la barra en banco.'),
